        self.assertIsInstance(Lock(), asyncio.Lock)
        self.assertIsInstance(Queue(), asyncio.Queue)
        self.assertIsInstance(Semaphore(), asyncio.Semaphore)


class TestIntrospection(unittest.TestCase):
