cat > "$OUTPUT_DIR/utils.py" <<'UTILS'
"""Utility helper functions."""

from typing import Any, Callable, Dict, List, Optional, Protocol, Set, TypeVar, Union


class Comparable(Protocol):
    def __lt__(self, other: Any) -> bool: ...


T = TypeVar("T")
CT = TypeVar("CT", bound=Comparable)
U = TypeVar("U")
K = TypeVar("K")
V = TypeVar("V")


def flatten(lst: List[List[T]]) -> List[T]:
    """Flatten a list of lists into a single list."""
    result: List[T] = []
    for item in lst:
        result.extend(item)
    return result


def chunk(lst: List[T], size: int) -> List[List[T]]:
    """Split a list into chunks of the specified size."""
    if size <= 0:
        raise ValueError("Chunk size must be positive")
    return [lst[i : i + size] for i in range(0, len(lst), size)]


def unique(lst: List[T]) -> List[T]:
    """Return a list of unique elements preserving order."""
    seen: Set[Any] = set()
    result: List[T] = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


def is_empty(value: Any) -> bool:
    """Check if a value is considered empty."""
    if value is None:
        return True
    if isinstance(value, (str, list, tuple, set, dict)):
        return len(value) == 0
    return False


def remove_none(lst: List[Any]) -> List[Any]:
    """Return a copy of lst with None values removed."""
    return [item for item in lst if item is not None]


def last(lst: List[T]) -> T:
    """Return the last element of a non-empty list."""
    if not lst:
        raise ValueError("List must not be empty")
    return lst[-1]


def first(lst: List[T]) -> T:
    """Return the first element of a non-empty list."""
    if not lst:
        raise ValueError("List must not be empty")
    return lst[0]


def second(lst: List[T]) -> T:
    """Return the second element of a non-empty list."""
    if len(lst) < 2:
        raise ValueError("List must have at least two elements")
    return lst[1]


def compact(lst: List[T]) -> List[T]:
    """Return a copy of lst with falsy values removed."""
    return [item for item in lst if item]


def take(lst: List[T], n: int) -> List[T]:
    """Return the first n elements of a list."""
    if n <= 0:
        return []
    return lst[:n]


def drop(lst: List[T], n: int) -> List[T]:
    """Return a list with the first n elements removed."""
    if n <= 0:
        return list(lst)
    return lst[n:]


def tail(lst: List[T], n: int) -> List[T]:
    """Return the last n elements of a list."""
    if n <= 0:
        return []
    if n >= len(lst):
        return list(lst)
    return lst[-n:]


def head(lst: List[T], n: int) -> List[T]:
    """Return the first n elements of a list (alias for take)."""
    return take(lst, n)


def rest(lst: List[T]) -> List[T]:
    """Return a list with the first element removed."""
    if not lst:
        return []
    return lst[1:]


def initial(lst: List[T]) -> List[T]:
    """Return all elements except the last."""
    if not lst:
        return []
    return lst[:-1]


def partition(lst: List[T], predicate: Callable[[T], bool]) -> List[List[T]]:
    """Split a list into two lists based on a predicate."""
    truthy: List[T] = []
    falsy: List[T] = []
    for item in lst:
        if predicate(item):
            truthy.append(item)
        else:
            falsy.append(item)
    return [truthy, falsy]


def group_by(lst: List[T], key: Callable[[T], K]) -> Dict[K, List[T]]:
    """Group elements by the result of a key function."""
    result: Dict[K, List[T]] = {}
    for item in lst:
        k = key(item)
        if k not in result:
            result[k] = []
        result[k].append(item)
    return result


def index_by(lst: List[T], key: Callable[[T], K]) -> Dict[K, T]:
    """Index elements by the result of a key function."""
    result: Dict[K, T] = {}
    for item in lst:
        result[key(item)] = item
    return result


def zip_with(lst1: List[T], lst2: List[U], fn: Callable[[T, U], V]) -> List[V]:
    """Zip two lists together using a combining function."""
    result: List[V] = []
    for a, b in zip(lst1, lst2):
        result.append(fn(a, b))
    return result


def concat(*lists: List[T]) -> List[T]:
    """Concatenate multiple lists into one."""
    result: List[T] = []
    for lst in lists:
        result.extend(lst)
    return result


def intersection(lst1: List[T], lst2: List[T]) -> List[T]:
    """Return elements that appear in both lists preserving order from lst1."""
    set2 = set(lst2)
    seen: Set[T] = set()
    result: List[T] = []
    for item in lst1:
        if item in set2 and item not in seen:
            seen.add(item)
            result.append(item)
    return result


def difference(lst1: List[T], lst2: List[T]) -> List[T]:
    """Return elements in lst1 that are not in lst2 preserving order."""
    set2 = set(lst2)
    result: List[T] = []
    for item in lst1:
        if item not in set2:
            result.append(item)
    return result


def union(lst1: List[T], lst2: List[T]) -> List[T]:
    """Return unique elements from both lists preserving order."""
    return unique(concat(lst1, lst2))


def pluck(lst: List[Dict[K, V]], key: K) -> List[V]:
    """Extract values for a key from a list of dictionaries."""
    result: List[V] = []
    for item in lst:
        if isinstance(item, dict) and key in item:
            result.append(item[key])
    return result


def pick(d: Dict[K, V], keys: List[K]) -> Dict[K, V]:
    """Pick specific keys from a dictionary."""
    result: Dict[K, V] = {}
    for key in keys:
        if key in d:
            result[key] = d[key]
    return result


def omit(d: Dict[K, V], keys: List[K]) -> Dict[K, V]:
    """Omit specific keys from a dictionary."""
    keys_set = set(keys)
    result: Dict[K, V] = {}
    for key, value in d.items():
        if key not in keys_set:
            result[key] = value
    return result


def merge(*dicts: Dict[K, V]) -> Dict[K, V]:
    """Merge multiple dictionaries, with later dicts taking precedence."""
    result: Dict[K, V] = {}
    for d in dicts:
        result.update(d)
    return result


def get(d: Dict[K, Any], key: K, default: Any = None) -> Any:
    """Get a value from a dictionary with a default."""
    if not isinstance(d, dict):
        return default
    return d.get(key, default)


def has_key(d: Dict[K, Any], key: K) -> bool:
    """Check if a dictionary has a key."""
    return isinstance(d, dict) and key in d


def range_list(start: int, stop: Optional[int] = None, step: int = 1) -> List[int]:
    """Create a list from a range."""
    if stop is None:
        return list(range(start))
    return list(range(start, stop, step))


def repeat(item: T, n: int) -> List[T]:
    """Repeat an item n times."""
    if n <= 0:
        return []
    return [item] * n


def sample(lst: List[T], n: int = 1) -> List[T]:
    """Return n random samples from a list (without replacement if possible)."""
    import random

    if n <= 0:
        return []
    if n >= len(lst):
        result = list(lst)
        random.shuffle(result)
        return result
    return random.sample(lst, n)


def shuffle(lst: List[T]) -> List[T]:
    """Return a shuffled copy of a list."""
    import random

    result = list(lst)
    random.shuffle(result)
    return result


def map_list(fn: Callable[[T], U], lst: List[T]) -> List[U]:
    """Map a function over a list (alias for list(map(...)))."""
    return [fn(item) for item in lst]


def filter_list(fn: Callable[[T], bool], lst: List[T]) -> List[T]:
    """Filter a list using a predicate (alias for list(filter(...)))."""
    return [item for item in lst if fn(item)]


def reduce_list(fn: Callable[[U, T], U], lst: List[T], initial: U) -> U:
    """Reduce a list using a function."""
    result = initial
    for item in lst:
        result = fn(result, item)
    return result


def for_each(fn: Callable[[T], Any], lst: List[T]) -> None:
    """Apply a function to each element of a list."""
    for item in lst:
        fn(item)


def find(lst: List[T], predicate: Callable[[T], bool]) -> Optional[T]:
    """Find the first element matching a predicate."""
    for item in lst:
        if predicate(item):
            return item
    return None


def find_index(lst: List[T], predicate: Callable[[T], bool]) -> int:
    """Find the index of the first element matching a predicate. Returns -1 if not found."""
    for i, item in enumerate(lst):
        if predicate(item):
            return i
    return -1


def some(lst: List[T], predicate: Callable[[T], bool]) -> bool:
    """Check if any element matches a predicate."""
    for item in lst:
        if predicate(item):
            return True
    return False


def every(lst: List[T], predicate: Callable[[T], bool]) -> bool:
    """Check if all elements match a predicate."""
    for item in lst:
        if not predicate(item):
            return False
    return True


def includes(lst: List[T], item: T) -> bool:
    """Check if a list contains an item."""
    return item in lst


def sum_list(lst: List[Union[int, float]]) -> Union[int, float]:
    """Sum all elements in a list."""
    return sum(lst)


def product(lst: List[Union[int, float]]) -> Union[int, float]:
    """Return the product of all elements in a list."""
    if not lst:
        raise ValueError("List must not be empty")
    result: Union[int, float] = 1
    for item in lst:
        result *= item
    return result


def take_while(lst: List[T], predicate: Callable[[T], bool]) -> List[T]:
    """Take elements from the beginning while predicate is true."""
    result: List[T] = []
    for item in lst:
        if predicate(item):
            result.append(item)
        else:
            break
    return result


def drop_while(lst: List[T], predicate: Callable[[T], bool]) -> List[T]:
    """Drop elements from the beginning while predicate is true."""
    result: List[T] = []
    dropping = True
    for item in lst:
        if dropping and predicate(item):
            continue
        dropping = False
        result.append(item)
    return result


def average(lst: List[Union[int, float]]) -> float:
    """Calculate the average of a list."""
    if not lst:
        raise ValueError("List must not be empty")
    return sum(lst) / len(lst)


def max_list(lst: List[CT]) -> CT:
    """Return the maximum element in a list."""
    if not lst:
        raise ValueError("List must not be empty")
    return max(lst)


def min_list(lst: List[CT]) -> CT:
    """Return the minimum element in a list."""
    if not lst:
        raise ValueError("List must not be empty")
    return min(lst)


def reverse(lst: List[T]) -> List[T]:
    """Return a reversed copy of a list."""
    return list(reversed(lst))


def count(lst: List[T], item: T) -> int:
    """Count occurrences of an item in a list."""
    return lst.count(item)


def count_by(lst: List[T], predicate: Callable[[T], bool]) -> int:
    """Count elements matching a predicate."""
    count_result = 0
    for item in lst:
        if predicate(item):
            count_result += 1
    return count_result


def to_dict(pairs: List[List[Any]]) -> Dict[Any, Any]:
    """Convert a list of pairs to a dictionary."""
    result: Dict[Any, Any] = {}
    for pair in pairs:
        if len(pair) >= 2:
            result[pair[0]] = pair[1]
    return result


def from_pairs(pairs: List[tuple]) -> Dict[Any, Any]:
    """Convert a list of tuples to a dictionary."""
    return dict(pairs)


def keys(d: Dict[K, V]) -> List[K]:
    """Return all keys of a dictionary as a list."""
    return list(d.keys())


def values(d: Dict[K, V]) -> List[V]:
    """Return all values of a dictionary as a list."""
    return list(d.values())


def items(d: Dict[K, V]) -> List[tuple]:
    """Return all items of a dictionary as a list of tuples."""
    return list(d.items())
UTILS

# --- stats.py ---
cat > "$OUTPUT_DIR/stats.py" <<'STATS'
"""Statistical utility functions for data analysis."""

import math
from typing import List, TypeVar

T = TypeVar("T", int, float)

__all__: List[str] = [
    "mean",
    "median",
    "mode",
    "multimode",
    "variance",
    "stddev",
    "skewness",
    "range",
    "min_value",
    "max_value",
    "midrange",
    "trimmed_mean",
    "sum_values",
    "sum_of_squares",
    "percentile",
    "iqr",
    "interquartile_range",
    "coefficient_of_variation",
    "geometric_mean",
    "harmonic_mean",
    "median_absolute_deviation",
    "weighted_mean",
    "kurtosis",
    "covariance",
    "correlation",
]


def _require_numbers(numbers: List[T | float], name: str = "numbers") -> None:
    if not isinstance(numbers, list):
        raise TypeError(f"{name} must be a list")
    if not numbers:
        raise ValueError(f"Cannot calculate {name.replace('numbers', 'values')} of empty list")
    for x in numbers:
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            raise TypeError(f"{name} must contain only numbers")


def _require_int(value: object, name: str) -> int:
    """Validate that *value* is an int, raising ``TypeError`` otherwise."""
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError(f"{name} must be an int, got {type(value).__name__}")
    return value


def mean(numbers: List[T | float]) -> float:
    """Return the arithmetic mean of a list of numbers.

    Args:
        numbers: A list of numeric values.

    Returns:
        The average of all numbers.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.

    Examples:
        >>> mean([1, 2, 3, 4, 5])
        3.0
        >>> mean([2, 4])
        3.0
    """
    _require_numbers(numbers, "numbers")
    return sum(numbers) / len(numbers)


def median(numbers: List[T | float]) -> float:
    """Return the median of a list of numbers.

    Args:
        numbers: A list of numeric values.

    Returns:
        The median value.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.

    Examples:
        >>> median([1, 2, 3, 4, 5])
        3
        >>> median([1, 2, 3, 4])
        2.5
    """
    _require_numbers(numbers, "numbers")
    sorted_nums = sorted(numbers)
    n = len(sorted_nums)
    if n % 2 == 1:
        return float(sorted_nums[n // 2])
    mid1 = sorted_nums[n // 2 - 1]
    mid2 = sorted_nums[n // 2]
    return (mid1 + mid2) / 2.0


def mode(numbers: List[T | float]) -> float:
    """Return the mode (most frequent value) of a list of numbers.

    If there is more than one mode, returns the first one encountered
    in terms of the value that appears first in sorted order of values.

    Args:
        numbers: A list of numeric values.

    Returns:
        The most frequently occurring value.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.

    Examples:
        >>> mode([1, 2, 2, 3, 4])
        2
        >>> mode([1, 1, 2, 2, 3])
        1
    """
    _require_numbers(numbers, "numbers")
    frequency: dict = {}
    for num in numbers:
        frequency[num] = frequency.get(num, 0) + 1
    max_count = max(frequency.values())
    for num in sorted(frequency.keys()):
        if frequency[num] == max_count:
            return float(num)
    raise ValueError("Cannot calculate mode of empty list")


def multimode(numbers: List[T | float]) -> List[float]:
    """Return the list of modes (most frequent values) of a list of numbers.

    Unlike :func:`mode`, which returns a single mode, this returns every value
    that shares the highest frequency, in the order each value first appears in
    *numbers*.

    Args:
        numbers: A list of numeric values.

    Returns:
        A list of the most frequently occurring values.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.

    Examples:
        >>> multimode([1, 2, 2, 3, 3])
        [2.0, 3.0]
        >>> multimode([1, 1, 2, 2])
        [1.0, 2.0]
    """
    _require_numbers(numbers, "numbers")
    frequency: dict = {}
    for num in numbers:
        frequency[num] = frequency.get(num, 0) + 1
    max_count = max(frequency.values())
    seen: set = set()
    result: List[float] = []
    for num in numbers:
        if frequency[num] == max_count and num not in seen:
            seen.add(num)
            result.append(float(num))
    return result


def variance(numbers: List[T | float], population: bool = True) -> float:
    """Return the variance of a list of numbers.

    Args:
        numbers: A list of numeric values.
        population: If True, calculate population variance (divide by n).
                    If False, calculate sample variance (divide by n-1).
                    Defaults to True.

    Returns:
        The variance.

    Raises:
        ValueError: If the list is empty, or if calculating sample variance
                    with fewer than 2 elements.
        TypeError: If numbers is not a list, contains non-numeric values,
                   or population is not a bool.
    """
    _require_numbers(numbers, "numbers")
    if not isinstance(population, bool):
        raise TypeError("population must be a bool")
    if not population and len(numbers) < 2:
        raise ValueError("Cannot calculate sample variance with fewer than 2 elements")
    avg = mean(numbers)
    squared_diff = sum((x - avg) ** 2 for x in numbers)
    if population:
        return squared_diff / len(numbers)
    return squared_diff / (len(numbers) - 1)


def stddev(numbers: List[T | float], population: bool = True) -> float:
    """Return the standard deviation of a list of numbers.

    Args:
        numbers: A list of numeric values.
        population: If True, calculate population std dev (divide by n).
                    If False, calculate sample std dev (divide by n-1).
                    Defaults to True.

    Returns:
        The standard deviation.

    Raises:
        ValueError: If the list is empty, or if calculating sample std dev
                    with fewer than 2 elements.
        TypeError: If numbers is not a list, contains non-numeric values,
                   or population is not a bool.
    """
    _require_numbers(numbers, "numbers")
    if not isinstance(population, bool):
        raise TypeError("population must be a bool")
    var = variance(numbers, population=population)
    return math.sqrt(var)


def skewness(numbers: List[T | float]) -> float:
    """Return the population skewness of a list of numbers.

    Skewness measures the asymmetry of a distribution about its mean. A
    symmetric distribution has skewness 0; a distribution with a longer
    right tail has positive skewness, and one with a longer left tail has
    negative skewness.

    Args:
        numbers: A list of numeric values.

    Returns:
        The population skewness of the numbers.

    Raises:
        ValueError: If the list is empty, has fewer than 3 elements, or if
            the standard deviation is 0.
        TypeError: If numbers is not a list or contains non-numeric values.

    Examples:
        >>> skewness([1, 2, 3])
        0.0
        >>> skewness([1, 1, 1, 1, 10])
        1.5
    """
    _require_numbers(numbers, "numbers")
    n = len(numbers)
    if n < 3:
        raise ValueError("Cannot calculate skewness with fewer than 3 elements")
    m = mean(numbers)
    s = stddev(numbers)
    if s == 0:
        raise ValueError("Cannot calculate skewness when standard deviation is 0")
    return float(sum(((x - m) / s) ** 3 for x in numbers) / n)


def range(numbers: List[T | float]) -> float:
    """Return the range (max - min) of a list of numbers.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.
    """
    _require_numbers(numbers, "numbers")
    return float(max(numbers) - min(numbers))


def min_value(numbers: List[T | float]) -> float:
    """Return the minimum value in a list of numbers.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.
    """
    _require_numbers(numbers, "numbers")
    return float(min(numbers))


def max_value(numbers: List[T | float]) -> float:
    """Return the maximum value in a list of numbers.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.
    """
    _require_numbers(numbers, "numbers")
    return float(max(numbers))


def midrange(numbers: List[T | float]) -> float:
    """Return the midrange of a list of numbers.

    The midrange is the arithmetic mean of the minimum and maximum values,
    a simple measure of central tendency.

    Args:
        numbers: A list of numeric values.

    Returns:
        The midrange of the numbers.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.

    Examples:
        >>> midrange([1, 2, 3, 4, 5])
        3.0
        >>> midrange([1, 9])
        5.0
    """
    _require_numbers(numbers, "numbers")
    return (min(numbers) + max(numbers)) / 2.0


def trimmed_mean(numbers: List[T | float], trim_count: int = 0) -> float:
    """Return the trimmed mean of a list of numbers.

    The *trim_count* smallest and *trim_count* largest values are discarded
    before computing the arithmetic mean of the remaining values. This makes
    the result robust to outliers. When *trim_count* is 0 (the default) the
    result is identical to :func:`mean`.

    Args:
        numbers: A list of numeric values.
        trim_count: How many values to drop from each end of the sorted
            list. Must be non-negative and strictly less than half the list
            length so that at least one value remains.

    Returns:
        The arithmetic mean of the interior values.

    Raises:
        ValueError: If the list is empty, if *trim_count* is negative, or if
            *trim_count* is greater than or equal to half the list length.
        TypeError: If *numbers* is not a list, contains non-numeric values,
            or *trim_count* is not an int.

    Examples:
        >>> trimmed_mean([1, 2, 3, 4, 5])
        3.0
        >>> trimmed_mean([1, 2, 3, 4, 5], trim_count=1)
        3.0
        >>> trimmed_mean([1, 2, 3, 4, 5, 6], trim_count=1)
        3.5
    """
    _require_numbers(numbers, "numbers")
    _require_int(trim_count, "trim_count")
    if trim_count < 0:
        raise ValueError("trim_count must be non-negative")
    n = len(numbers)
    if trim_count >= n / 2:
        raise ValueError(
            "trim_count must be less than half the list length, "
            f"got {trim_count} for list of length {n}"
        )
    sorted_nums = sorted(numbers)
    trimmed = sorted_nums[trim_count: n - trim_count]
    return sum(trimmed) / len(trimmed)


def sum_values(numbers: List[T | float]) -> float:
    """Return the sum of all values in a list of numbers.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.
    """
    _require_numbers(numbers, "numbers")
    return float(sum(numbers))


def sum_of_squares(numbers: List[T | float]) -> float:
    """Return the sum of the squares of the values in a list of numbers.

    Args:
        numbers: A list of numeric values.

    Returns:
        The sum of the squared values.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.

    Examples:
        >>> sum_of_squares([1, 2, 3])
        14.0
    """
    _require_numbers(numbers, "numbers")
    return float(sum(x * x for x in numbers))


def percentile(numbers: List[T | float], p: float) -> float:
    """Return the p-th percentile of a list of numbers (linear interpolation).

    Args:
        numbers: A list of numeric values.
        p: The percentile to compute, between 0 and 100 inclusive.

    Returns:
        The p-th percentile value.

    Raises:
        ValueError: If the list is empty, or if p is outside [0, 100].
        TypeError: If numbers is not a list, contains non-numeric values,
                   or p is not a number.

    Examples:
        >>> percentile([1, 2, 3, 4, 5], 50)
        3.0
        >>> percentile([1, 2, 3, 4], 50)
        2.5
    """
    _require_numbers(numbers, "numbers")
    if not isinstance(p, (int, float)) or isinstance(p, bool):
        raise TypeError("p must be a number")
    if p < 0 or p > 100:
        raise ValueError("p must be between 0 and 100")
    sorted_nums = sorted(float(x) for x in numbers)
    if p == 0:
        return sorted_nums[0]
    if p == 100:
        return sorted_nums[-1]
    k = (len(sorted_nums) - 1) * (p / 100.0)
    f = math.floor(k)
    c = math.ceil(k)
    if f == c:
        return sorted_nums[int(k)]
    return sorted_nums[f] * (c - k) + sorted_nums[c] * (k - f)


def iqr(numbers: List[T | float]) -> float:
    """Return the interquartile range (Q3 - Q1)."""
    _require_numbers(numbers, "numbers")
    q1 = percentile(numbers, 25)
    q3 = percentile(numbers, 75)
    return float(q3 - q1)


def interquartile_range(numbers: List[T | float]) -> float:
    """Return the interquartile range (Q3 - Q1).

    This is an alias for :func:`iqr`.
    """
    return iqr(numbers)


def coefficient_of_variation(numbers: List[T | float], population: bool = True) -> float:
    """Return the coefficient of variation (stddev / mean)."""
    _require_numbers(numbers, "numbers")
    if not isinstance(population, bool):
        raise TypeError("population must be a bool")
    m = mean(numbers)
    if m == 0:
        raise ValueError("Cannot calculate coefficient of variation when mean is 0")
    s = stddev(numbers, population=population)
    return float(abs(s) / abs(m))


def geometric_mean(numbers: List[T | float]) -> float:
    """Return the geometric mean."""
    _require_numbers(numbers, "numbers")
    product = 1.0
    for x in numbers:
        if float(x) <= 0:
            raise ValueError("All numbers must be positive")
        product *= float(x)
    return float(product ** (1.0 / len(numbers)))


def harmonic_mean(numbers: List[T | float]) -> float:
    """Return the harmonic mean."""
    _require_numbers(numbers, "numbers")
    total = 0.0
    for x in numbers:
        if float(x) <= 0:
            raise ValueError("All numbers must be positive")
        total += 1.0 / float(x)
    return float(len(numbers) / total)


def median_absolute_deviation(numbers: List[T | float]) -> float:
    """Return the median absolute deviation of a list of numbers.

    The median absolute deviation (MAD) is the median of the absolute
    deviations of each number from the median of the list. It is a robust
    measure of statistical dispersion.

    Args:
        numbers: A list of numeric values.

    Returns:
        The median absolute deviation of the numbers.

    Raises:
        ValueError: If the list is empty.
        TypeError: If numbers is not a list or contains non-numeric values.

    Examples:
        >>> median_absolute_deviation([1, 2, 3])
        1.0
        >>> median_absolute_deviation([2, 2, 2, 2])
        0.0
    """
    _require_numbers(numbers, "numbers")
    med = median(numbers)
    deviations = [abs(x - med) for x in numbers]
    return median(deviations)


def weighted_mean(values: List[T | float], weights: List[T | float]) -> float:
    """Return the weighted arithmetic mean.

    Args:
        values: A list of numeric values.
        weights: A list of weights for each value (same length as values).

    Returns:
        The weighted arithmetic mean.

    Raises:
        ValueError: If values or weights is empty, lengths differ, or any weight is non-positive.
        TypeError: If inputs are not lists or contain non-numeric values.
    """
    _require_numbers(values, "values")
    _require_numbers(weights, "weights")
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    total_weight = 0.0
    weighted_sum = 0.0
    for v, w in zip(values, weights):
        w_f = float(w)
        if w_f <= 0:
            raise ValueError("weights must be positive")
        v_f = float(v)
        total_weight += w_f
        weighted_sum += v_f * w_f
    if total_weight == 0:
        raise ValueError("weights must sum to a positive value")
    return float(weighted_sum / total_weight)


def kurtosis(numbers: List[T | float]) -> float:
    """Return the excess kurtosis of a list of numbers.

    Kurtosis measures the "tailedness" of a distribution. This function
    returns the excess kurtosis (kurtosis minus 3), so a normal
    distribution has an excess kurtosis of 0.

    Args:
        numbers: A list of numeric values.

    Returns:
        The excess kurtosis of the numbers.

    Raises:
        ValueError: If the list has fewer than 4 elements, or if the
            standard deviation is 0.
        TypeError: If numbers is not a list or contains non-numeric values.

    Examples:
        >>> kurtosis([1, 2, 3, 4, 5])
        -1.3
    """
    _require_numbers(numbers, "numbers")
    n = len(numbers)
    if n < 4:
        raise ValueError("Cannot calculate kurtosis with fewer than 4 elements")
    m = mean(numbers)
    s = stddev(numbers)
    if s == 0:
        raise ValueError("Cannot calculate kurtosis when standard deviation is 0")
    return float(sum(((x - m) / s) ** 4 for x in numbers) / n - 3.0)


def _require_same_length(x: List[T | float], y: List[T | float], name: str = "values") -> None:
    """Validate that *x* and *y* are numeric lists of equal length."""
    _require_numbers(x, name)
    _require_numbers(y, "weights")
    if len(x) != len(y):
        raise ValueError(f"{name} and weights must have the same length")


def covariance(x: List[T | float], y: List[T | float], population: bool = True) -> float:
    """Return the covariance between two lists of numbers.

    Args:
        x: The first list of numeric values.
        y: The second list of numeric values (same length as *x*).
        population: If True, divide by *n* (population covariance). If False,
            divide by *n - 1* (sample covariance). Defaults to True.

    Returns:
        The covariance between *x* and *y*.

    Raises:
        ValueError: If the lists are empty, have different lengths, or if
            sample covariance is requested with fewer than 2 elements.
        TypeError: If inputs are not lists, contain non-numeric values, or
            *population* is not a bool.
    """
    _require_same_length(x, y, "values")
    if not isinstance(population, bool):
        raise TypeError("population must be a bool")
    if not population and len(x) < 2:
        raise ValueError("Cannot calculate sample covariance with fewer than 2 elements")
    mx = mean(x)
    my = mean(y)
    n = len(x)
    cov = sum((xi - mx) * (yi - my) for xi, yi in zip(x, y))
    if population:
        return float(cov / n)
    return float(cov / (n - 1))


def correlation(x: List[T | float], y: List[T | float]) -> float:
    """Return the Pearson correlation coefficient between two lists of numbers.

    The correlation measures the strength and direction of a linear
    relationship between *x* and *y*, ranging from -1 (perfect negative
    correlation) to 1 (perfect positive correlation). A value of 0 means no
    linear correlation.

    Args:
        x: The first list of numeric values.
        y: The second list of numeric values (same length as *x*).

    Returns:
        The Pearson correlation coefficient.

    Raises:
        ValueError: If the lists are empty, have different lengths, have
            fewer than 2 elements, or if either list has zero standard
            deviation.
        TypeError: If inputs are not lists or contain non-numeric values.
    """
    _require_same_length(x, y, "values")
    n = len(x)
    if n < 2:
        raise ValueError("Cannot calculate correlation with fewer than 2 elements")
    sx = stddev(x)
    sy = stddev(y)
    if sx == 0 or sy == 0:
        raise ValueError("Cannot calculate correlation when standard deviation is 0")
    cov = covariance(x, y, population=True)
    return float(cov / (sx * sy))
STATS

