    def test_multiple_modes(self) -> None:
        self.assertEqual(multimode([1, 1, 2, 2, 3]), [1.0, 2.0])

    def test_all_unique(self) -> None:
        self.assertEqual(multimode([1, 2, 3]), [1.0, 2.0, 3.0])

    def test_order_of_first_appearance(self) -> None:
