class TestTrimmedMean(unittest.TestCase):
    def test_default_is_mean(self) -> None:
        self.assertEqual(trimmed_mean([1, 2, 3, 4, 5]), 3.0)

    def test_trim_one_from_each_end(self) -> None:
        self.assertEqual(trimmed_mean([1, 2, 3, 4, 5], trim_count=1), 3.0)

    def test_trim_even_list(self) -> None:
        self.assertEqual(trimmed_mean([1, 2, 3, 4, 5, 6], trim_count=1), 3.5)

    def test_trim_two_from_each_end(self) -> None:
        self.assertEqual(
            trimmed_mean([1, 2, 3, 4, 5, 6, 7, 8], trim_count=2),
            4.5,
        )

    def test_unsorted_input(self) -> None:
        self.assertEqual(trimmed_mean([9, 1, 5, 2, 8], trim_count=1), 5.0)

    def test_single_element(self) -> None:
        self.assertEqual(trimmed_mean([7]), 7.0)

    def test_negative_values(self) -> None:
        self.assertEqual(trimmed_mean([-3, -1, 0, 1, 3], trim_count=1), 0.0)

    def test_float_values(self) -> None:
        self.assertAlmostEqual(trimmed_mean([1.0, 2.0, 100.0], trim_count=1), 2.0)

    def test_empty_raises(self) -> None:
        with self.assertRaises(ValueError):
            trimmed_mean([])

    def test_negative_trim_count_raises(self) -> None:
        with self.assertRaises(ValueError):
            trimmed_mean([1, 2, 3], trim_count=-1)

    def test_trim_count_too_large_raises(self) -> None:
        with self.assertRaises(ValueError):
            trimmed_mean([1, 2, 3], trim_count=2)
        with self.assertRaises(ValueError):
            trimmed_mean([1, 2, 3, 4], trim_count=2)

    def test_rejects_non_list(self) -> None:
        with self.assertRaises(TypeError):
            trimmed_mean((1, 2, 3))  # type: ignore[arg-type]

    def test_rejects_non_numeric(self) -> None:
        with self.assertRaises(TypeError):
            trimmed_mean([1, 2, "a"])  # type: ignore[type-var]

    def test_rejects_bool(self) -> None:
        with self.assertRaises(TypeError):
            trimmed_mean([True, 1, 2])  # type: ignore[type-var]

    def test_rejects_non_int_trim_count(self) -> None:
        with self.assertRaises(TypeError):
            trimmed_mean([1, 2, 3], 1.5)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            trimmed_mean([1, 2, 3], True)  # type: ignore[arg-type]


if __name__ == "__main__":
    unittest.main()
TESTSTATS

# --- math_utils.py ---
cat > "$OUTPUT_DIR/math_utils.py" <<'MATH'
"""Mathematical utility functions."""

import math


def factorial(n: int) -> int:
    """Calculate the factorial of a non-negative integer n.

    Args:
        n: The number to calculate factorial for.

    Returns:
        The factorial of n (n!).

    Raises:
        ValueError: If n is negative.
        OverflowError: If n is too large.

    Examples:
        >>> factorial(0)
        1
        >>> factorial(5)
        120
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    if n > 20:  # Prevent large numbers that might cause issues
        result = 1
        for i in range(2, n + 1):
            result *= i
        return result
    return math.factorial(n)


def fibonacci(n: int) -> int:
    """Calculate the nth Fibonacci number.

    Args:
        n: The index of the Fibonacci number (n >= 0).

    Returns:
        The nth Fibonacci number.

    Raises:
        ValueError: If n is negative.

    Examples:
        >>> fibonacci(0)
        0
        >>> fibonacci(1)
        1
        >>> fibonacci(5)
        5
    """
    if n < 0:
        raise ValueError("Fibonacci is not defined for negative numbers")
    if n == 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b


def gcd(a: int, b: int) -> int:
    """Calculate the Greatest Common Divisor of two integers.

    Args:
        a: First integer.
        b: Second integer.

    Returns:
        The GCD of a and b.

    Examples:
        >>> gcd(48, 18)
        6
        >>> gcd(17, 13)
        1
    """
    return math.gcd(a, b)


def lcm(a: int, b: int) -> int:
    """Calculate the Least Common Multiple of two integers.

    Args:
        a: First integer.
        b: Second integer.

    Returns:
        The LCM of a and b.

    Examples:
        >>> lcm(4, 6)
        12
        >>> lcm(3, 5)
        15
    """
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)


def is_prime(n: int) -> bool:
    """Check if a number is prime.

    Args:
        n: The number to check.

    Returns:
        True if n is prime, False otherwise.

    Raises:
        ValueError: If n < 2.

    Examples:
        >>> is_prime(2)
        True
        >>> is_prime(9)
        False
        >>> is_prime(17)
        True
    """
    if n < 2:
        raise ValueError("Prime check is only defined for integers >= 2")
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


def clamp(value: float, min_val: float, max_val: float) -> float:
    """Clamp a value between min_val and max_val.

    Args:
        value: The value to clamp.
        min_val: The minimum allowed value.
        max_val: The maximum allowed value.

    Returns:
        The clamped value.

    Raises:
        ValueError: If min_val > max_val.

    Examples:
        >>> clamp(5, 0, 10)
        5
        >>> clamp(-5, 0, 10)
        0
        >>> clamp(15, 0, 10)
        10
    """
    if min_val > max_val:
        raise ValueError("min_val must be <= max_val")
    return max(min_val, min(value, max_val))


def is_even(value: int) -> bool:
    """Return True if *value* is an even integer."""
    if not isinstance(value, int):
        raise TypeError(f"value must be an int, got {type(value).__name__}")
    return value % 2 == 0
MATH

# --- data_utils.py ---
cat > "$OUTPUT_DIR/data_utils.py" <<'DATA'
"""Data utility functions."""

import copy
from typing import Any, Dict, Iterable, List, Set, TypeVar

K = TypeVar("K")
V = TypeVar("V")


def deep_copy(obj: Any) -> Any:
    """Create a deep copy of an object."""
    try:
        return copy.deepcopy(obj)
    except Exception:
        return copy.copy(obj)


def merge_dicts(*dicts: Dict[Any, Any]) -> Dict[Any, Any]:
    """Merge multiple dictionaries, later values override earlier ones."""
    result: Dict[Any, Any] = {}
    for d in dicts:
        if d:
            result.update(d)
    return result


def pick(d: Dict[K, V], keys: Iterable[K]) -> Dict[K, V]:
    """Return a new dict with only specified keys."""
    key_set: Set[K] = set(keys)
    return {k: d[k] for k in d if k in key_set}


def omit(d: Dict[K, V], keys: Iterable[K]) -> Dict[K, V]:
    """Return a new dict without specified keys."""
    key_set: Set[K] = set(keys)
    return {k: v for k, v in d.items() if k not in key_set}


def flatten_dict(d: Dict[str, Any], parent_key: str = "", sep: str = ".") -> Dict[str, Any]:
    """Flatten nested dict to dot-notation keys."""
    items: List[tuple] = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep).items())
        else:
            items.append((new_key, v))
    return dict(items)
DATA

# --- datetime_utils.py ---
cat > "$OUTPUT_DIR/datetime_utils.py" <<'DATETIME'
"""Date and time utility functions."""

from datetime import datetime, timedelta
from typing import Union

DateTimeLike = Union[str, datetime]


def parse_datetime(value: str, fmt: str = "%Y-%m-%d %H:%M:%S") -> datetime:
    """Parse a string into a datetime object.

    Args:
        value: The string to parse.
        fmt: The expected format string. Defaults to ``%Y-%m-%d %H:%M:%S``.

    Returns:
        The parsed datetime object.

    Raises:
        ValueError: If the string does not match the format.
    """
    return datetime.strptime(value, fmt)


def format_datetime(dt: datetime, fmt: str = "%Y-%m-%d %H:%M:%S") -> str:
    """Format a datetime object as a string.

    Args:
        dt: The datetime to format.
        fmt: The desired format string. Defaults to ``%Y-%m-%d %H:%M:%S``.

    Returns:
        The formatted string.
    """
    return dt.strftime(fmt)


def days_between(start: DateTimeLike, end: DateTimeLike) -> int:
    """Return the absolute number of whole days between two dates.

    Args:
        start: A datetime or parseable string (format ``%Y-%m-%d``).
        end: A datetime or parseable string (format ``%Y-%m-%d``).

    Returns:
        The absolute difference in days.

    Raises:
        ValueError: If a string argument cannot be parsed.
    """
    start_dt = _coerce_datetime(start, "%Y-%m-%d")
    end_dt = _coerce_datetime(end, "%Y-%m-%d")
    delta = end_dt - start_dt
    return abs(delta.days)


def is_leap_year(year: int) -> bool:
    """Return True if *year* is a leap year.

    Args:
        year: The year to check.

    Returns:
        True if the year is a leap year, False otherwise.

    Raises:
        ValueError: If year is less than 1.
    """
    if year < 1:
        raise ValueError("Year must be a positive integer.")
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)


def add_days(dt: DateTimeLike, days: int) -> datetime:
    """Add (or subtract, if negative) a number of days to a datetime.

    Args:
        dt: A datetime or a string parseable with ``%Y-%m-%d``/``%Y-%m-%d %H:%M:%S``.
        days: The number of days to add. May be negative.

    Returns:
        A new datetime shifted by the given number of days.

    Raises:
        ValueError: If a string argument cannot be parsed.
    """
    dt_val = _coerce_datetime(dt, "%Y-%m-%d", "%Y-%m-%d %H:%M:%S")
    return dt_val + timedelta(days=days)


def get_weekday_name(dt: DateTimeLike) -> str:
    """Return the full weekday name for a given date.

    Args:
        dt: A datetime or a string parseable with ``%Y-%m-%d``.

    Returns:
        The weekday name (e.g. ``Monday``).

    Raises:
        ValueError: If a string argument cannot be parsed.
    """
    dt_val = _coerce_datetime(dt, "%Y-%m-%d")
    return dt_val.strftime("%A")


def _coerce_datetime(value: DateTimeLike, *formats: str) -> datetime:
    """Coerce a value into a datetime, trying multiple formats if needed.

    Args:
        value: A datetime (returned as-is) or a string to parse.
        *formats: Format strings to try when parsing.

    Returns:
        The resulting datetime.

    Raises:
        ValueError: If value is a string that matches none of the formats.
    """
    if isinstance(value, datetime):
        return value
    for fmt in formats:
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            continue
    raise ValueError(f"Could not parse '{value}'. Expected formats: {list(formats)}")
DATETIME
