    def test_n_too_large_raises(self) -> None:
        with self.assertRaises(ValueError):
            random_sample([1, 2, 3], 4)

    def test_seeded_is_reproducible(self) -> None:
        self.assertEqual(
            random_sample([1, 2, 3, 4, 5], 2, seed=7),
