class TestLinecacheUtils(unittest.TestCase):
    def setUp(self):
        self.fd, self.path = tempfile.mkstemp()
        with os.fdopen(self.fd, "w") as f:
            f.write("first\nsecond\nthird\n")

    def tearDown(self):
        os.remove(self.path)
        clearcache()

