cat > "$OUTPUT_DIR/cache_utils.py" <<'CACHEUTILS'
"""Caching utilities for memoizing function results.

This module provides a small, consistent API around function result caching,
including a ``memoize`` decorator factory, a ``clear_cache`` helper to invalidate
stored results, and a ``cache_info`` helper to inspect cache statistics.
"""

import functools
from typing import Any, Callable, Dict, List, Optional, Tuple, TypeVar, cast

F = TypeVar("F", bound=Callable[..., Any])

__all__: List[str] = [
    "cache_info",
    "clear_cache",
    "memoize",
]


def memoize(
    maxsize: Optional[int] = 128,
    typed: bool = False,
) -> Callable[[F], F]:
    """Decorator factory that caches a function's return values.

    The wrapped function stores results keyed by its call arguments so that
    subsequent invocations with the same arguments return the cached value
    without re-executing the body. ``functools.wraps`` is used, so the
    decorated function's metadata (``__name__``, ``__doc__``, etc.) is
    preserved.

    Args:
        maxsize: The maximum number of cached entries to retain. When the
            cache exceeds this size, the least-recently-used entry is evicted.
            Pass ``None`` for an unbounded cache. Defaults to ``128``.
        typed: If ``True``, arguments of the same value but different types
            (e.g. ``1`` and ``1.0``) are cached separately. Defaults to
            ``False``.

    Returns:
        A decorator that wraps a function with caching behavior.

    Example:
        >>> @memoize()
        ... def square(n: int) -> int:
        ...     return n * n
        >>> square(4)
        16
    """
    if maxsize is not None and (not isinstance(maxsize, int) or isinstance(maxsize, bool)):
        raise TypeError("maxsize must be an integer or None")
    if maxsize is not None and maxsize < 1:
        raise ValueError("maxsize must be a positive integer or None")

    def decorator(func: F) -> F:
        cache: Dict[Any, Any] = {}
        order: List[Any] = []
        hits = [0]
        misses = [0]

        def _make_key(args: Tuple[Any, ...], kwargs: Dict[str, Any]) -> Any:
            """Build a hashable cache key from positional and keyword arguments."""
            key_args: Tuple[Any, ...] = tuple(args)
            key_kwargs: Tuple[Tuple[str, Any], ...] = tuple(sorted(kwargs.items()))
            if typed:
                return (key_args, key_kwargs, tuple(type(a) for a in args))
            return (key_args, key_kwargs)

        def _evict_if_needed() -> None:
            """Evict the least-recently-used entry when the cache is full."""
            if maxsize is None or len(cache) <= maxsize:
                return
            # Evict the oldest key that is still present.
            for old_key in order:
                if old_key in cache:
                    cache.pop(old_key, None)
                    order.remove(old_key)
                    return

        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            key = _make_key(args, kwargs)
            if key in cache:
                hits[0] += 1
                return cache[key]
            misses[0] += 1
            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)
            _evict_if_needed()
            return result

        def clear() -> None:
            """Remove all cached entries and reset statistics."""
            cache.clear()
            order.clear()
            hits[0] = 0
            misses[0] = 0

        def info() -> Dict[str, Any]:
            """Return a dictionary describing the current cache state."""
            return {
                "hits": hits[0],
                "misses": misses[0],
                "maxsize": maxsize,
                "currsize": len(cache),
            }

        # Attach helpers to the wrapped function so callers can introspect
        # or invalidate the cache without needing to keep a separate reference.
        wrapper.clear_cache = clear  # type: ignore[attr-defined]
        wrapper.cache_info = info  # type: ignore[attr-defined]
        return cast(F, wrapper)

    return decorator


def clear_cache(func: F) -> None:
    """Clear the cache of a function decorated with :func:`memoize`.

    Args:
        func: A function previously decorated with :func:`memoize`.

    Raises:
        TypeError: If ``func`` does not expose a ``clear_cache`` attribute,
            meaning it was not memoized.

    Example:
        >>> @memoize()
        ... def add(a: int, b: int) -> int:
        ...     return a + b
        >>> add(1, 2)
        3
        >>> clear_cache(add)
    """
    clear = getattr(func, "clear_cache", None)
    if not callable(clear):
        raise TypeError("clear_cache can only be used on functions decorated with memoize")
    clear()


def cache_info(func: F) -> Dict[str, Any]:
    """Return cache statistics for a function decorated with :func:`memoize`.

    Args:
        func: A function previously decorated with :func:`memoize`.

    Returns:
        A dictionary with ``hits``, ``misses``, ``maxsize``, and ``currsize``
        keys describing the current state of the cache.

    Raises:
        TypeError: If ``func`` does not expose a ``cache_info`` attribute,
            meaning it was not memoized.

    Example:
        >>> @memoize()
        ... def mul(a: int, b: int) -> int:
        ...     return a * b
        >>> mul(2, 3)
        6
        >>> info = cache_info(mul)
        >>> info["misses"]
        1
    """
    info = getattr(func, "cache_info", None)
    if not callable(info):
        raise TypeError("cache_info can only be used on functions decorated with memoize")
    return cast(Dict[str, Any], info())
CACHEUTILS
# --- context_utils.py ---
cat > "$OUTPUT_DIR/context_utils.py" <<'CONTEXTUTILS'
"""Context manager utilities.

This module provides reusable context managers for temporarily altering
the runtime environment (working directory, environment variables, and
standard streams) and restoring it on exit, using only the standard
library. It complements :mod:`temp_utils`, which covers temporary
files and directories.
"""

from __future__ import annotations

import os
import sys
from contextlib import AbstractContextManager, contextmanager
from typing import Any, Iterator, Mapping, TextIO

__all__: list[str] = [
    "chdir",
    "temp_environ",
    "redirect_stdout",
    "redirect_stderr",
    "suppress",
]


def chdir(path: Any) -> AbstractContextManager[None]:
    """Temporarily change the current working directory.

    Args:
        path: The directory to change into for the duration of the
            context. Accepts a string or any :class:`os.PathLike`
            object.

    Yields:
        None. The previous working directory is restored on exit,
        even if an exception is raised within the context.

    Raises:
        TypeError: If ``path`` is not a string or :class:`os.PathLike`.
        FileNotFoundError: If ``path`` does not exist.
        NotADirectoryError: If ``path`` is not a directory.
    """
    if not isinstance(path, (str, os.PathLike)):
        raise TypeError("path must be a string or os.PathLike")
    return _chdir(path)


@contextmanager
def _chdir(path: Any) -> Iterator[None]:
    previous = os.getcwd()
    os.chdir(os.fspath(path))
    try:
        yield
    finally:
        os.chdir(previous)


def temp_environ(
    updates: Mapping[str, str],
    *,
    clear: bool = False,
) -> AbstractContextManager[None]:
    """Temporarily update environment variables.

    Args:
        updates: Environment variables to set for the duration of the
            context.
        clear: When true, remove all existing environment variables
            before applying ``updates`` for the duration of the
            context.

    Yields:
        None. The previous environment is restored on exit, even if an
        exception is raised within the context.

    Raises:
        TypeError: If ``updates`` is not a mapping of strings to
            strings.
    """
    if not isinstance(updates, Mapping):
        raise TypeError("updates must be a mapping of strings to strings")
    for key, value in updates.items():
        if not isinstance(key, str) or not isinstance(value, str):
            raise TypeError("updates must be a mapping of strings to strings")
    return _temp_environ(updates, clear=clear)


@contextmanager
def _temp_environ(updates: Mapping[str, str], clear: bool = False) -> Iterator[None]:
    snapshot = dict(os.environ)
    if clear:
        os.environ.clear()
    os.environ.update(updates)
    try:
        yield
    finally:
        os.environ.clear()
        os.environ.update(snapshot)


def redirect_stdout(target: TextIO) -> AbstractContextManager[None]:
    """Temporarily redirect :data:`sys.stdout`.

    Args:
        target: The file-like object to write standard output to for
            the duration of the context.

    Yields:
        None. The previous ``sys.stdout`` is restored on exit, even if
        an exception is raised within the context.

    Raises:
        TypeError: If ``target`` is not a file-like object with a
            ``write`` method.
    """
    if not hasattr(target, "write"):
        raise TypeError("target must be a file-like object with a write method")
    return _redirect_stream(sys, "stdout", target)


def redirect_stderr(target: TextIO) -> AbstractContextManager[None]:
    """Temporarily redirect :data:`sys.stderr`.

    Args:
        target: The file-like object to write standard error to for
            the duration of the context.

    Yields:
        None. The previous ``sys.stderr`` is restored on exit, even if
        an exception is raised within the context.

    Raises:
        TypeError: If ``target`` is not a file-like object with a
            ``write`` method.
    """
    if not hasattr(target, "write"):
        raise TypeError("target must be a file-like object with a write method")
    return _redirect_stream(sys, "stderr", target)


@contextmanager
def _redirect_stream(module: Any, name: str, target: TextIO) -> Iterator[None]:
    # Save current and restore to the "original" underlying stream as expected by tests
    original = getattr(module, name)
    # Prefer the builtin original if available for stdout/stderr
    if name == "stdout":
        original_to_restore = getattr(sys, "__stdout__", original)
    elif name == "stderr":
        original_to_restore = getattr(sys, "__stderr__", original)
    else:
        original_to_restore = original
    setattr(module, name, target)
    try:
        yield
    finally:
        setattr(module, name, original_to_restore)


def suppress(*exceptions: type[BaseException]) -> AbstractContextManager[None]:
    """Suppress the listed exceptions if raised within the context.

    Args:
        *exceptions: Exception types to silence. Any exception not in
            this list propagates normally.

    Yields:
        None. When a listed exception is raised, it is swallowed and
        execution continues after the context block.
    """
    return _suppress(exceptions)


@contextmanager
def _suppress(exceptions: tuple[type[BaseException], ...]) -> Iterator[None]:
    try:
        yield
    except exceptions:  # noqa: BLE001 - intentionally suppress listed exceptions
        return
CONTEXTUTILS
