"""Tests for operator_utils."""

import unittest

from operator_utils import (
    add,
    between,
    clamp,
    divide,
    identity,
    modulo,
    multiply,
    negate,
    power,
    subtract,
)


class TestOperatorUtils(unittest.TestCase):
