    def test_invalid_types(self):
        with self.assertRaises(ValueError):
            chunk_iterable([1, 2, 3], 0)
        with self.assertRaises(ValueError):
            chunk_iterable([1, 2, 3], -1)
        with self.assertRaises(TypeError):
            chunk_iterable([1, 2, 3], "x")


