    insort_left(a, 2)
    assert a == [1, 2, 3, 5]
    insort_right(a, 3)
    assert a == [1, 2, 3, 3, 5]


def test_find():
    a = [1, 2, 2, 3]
    assert find_leftmost(a, 2) == 1
    assert find_rightmost(a, 2) == 2
    assert find_leftmost(a, 9) is None
    assert find_rightmost(a, 9) is None
