"""Tests for shutil_utils module."""

import tempfile
import unittest
from pathlib import Path

from shutil_utils import (
    copy_file,
    copy_tree,
    disk_usage,
    make_archive,
    move,
    remove_tree,
    unpack_archive,
    which,
)


class TestShutilUtils(unittest.TestCase):
    def setUp(self) -> None:
        self.temp_dir = tempfile.mkdtemp()
        self.src = Path(self.temp_dir) / "src"
        self.dst = Path(self.temp_dir) / "dst"
        self.src.mkdir()

    def tearDown(self) -> None:
        import shutil

        shutil.rmtree(self.temp_dir, ignore_errors=True)

    def test_copy_file(self) -> None:
        (self.src / "a.txt").write_text("hello")
        result = copy_file(self.src / "a.txt", self.dst / "a.txt")
        self.assertTrue(Path(result).exists())
        self.assertEqual(Path(result).read_text(), "hello")

    def test_copy_tree(self) -> None:
        (self.src / "a.txt").write_text("hello")
        result = copy_tree(self.src, self.dst)
        self.assertTrue(Path(result).exists())
        self.assertTrue((self.dst / "a.txt").exists())

    def test_move(self) -> None:
        (self.src / "a.txt").write_text("hello")
        result = move(self.src / "a.txt", self.dst / "a.txt")
        self.assertTrue(Path(result).exists())
        self.assertFalse((self.src / "a.txt").exists())

    def test_remove_tree(self) -> None:
        d = Path(self.temp_dir) / "removeme"
        d.mkdir()
        (d / "f.txt").write_text("x")
        remove_tree(d)
        self.assertFalse(d.exists())

    def test_disk_usage(self) -> None:
        usage = disk_usage(self.temp_dir)
        self.assertTrue(hasattr(usage, "total"))

    def test_make_unpack_archive(self) -> None:
        (self.src / "a.txt").write_text("hello")
        base = Path(self.temp_dir) / "archive"
        path = make_archive(base, "zip", self.src)
        self.assertTrue(Path(path).exists())
        extract = Path(self.temp_dir) / "extracted"
        extract.mkdir()
        unpack_archive(path, extract)
        self.assertTrue((extract / "a.txt").exists())

    def test_which(self) -> None:
        self.assertIsNotNone(which("python3"))
        self.assertIsNone(which("definitely-not-a-command-xyz"))
TEST_SHUTIL_UTILS

# --- interval_utils.py ---
cat > "$OUTPUT_DIR/interval_utils.py" <<'INTERVALUTILS'
"""Interval utilities.

This module provides utilities for working with closed numeric intervals
of the form ``(low, high)`` where ``low <= high``. It supports
normalization, containment, overlap, intersection, union/merge, length,
and validation operations.
"""

from __future__ import annotations

from typing import Optional, Tuple

Interval = Tuple[float, float]

__all__ = [
    "Interval",
    "normalize_interval",
    "is_valid_interval",
    "interval_contains",
    "interval_overlaps",
    "interval_intersection",
    "interval_union",
    "merge_intervals",
    "interval_length",
    "interval_midpoint",
    "interval_distance",
    "interval_is_subset",
    "interval_shift",
    "interval_symmetric_difference",
]


def _is_number(value: object) -> bool:
    """Return True if *value* is a real int or float (excluding booleans)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def normalize_interval(low: float, high: float) -> Interval:
    """Return ``(low, high)`` with ``low <= high``.

    The two endpoints are swapped when necessary so the result is always a
    valid, ordered interval.

    Args:
        low: One endpoint of the interval.
        high: The other endpoint of the interval.

    Returns:
        A tuple ``(min, max)`` representing the normalized interval.

    Raises:
        TypeError: If either endpoint is not a real number.
    """
    if not _is_number(low):
        raise TypeError(f"low must be a real number, got {type(low).__name__}")
    if not _is_number(high):
        raise TypeError(f"high must be a real number, got {type(high).__name__}")
    return (min(low, high), max(low, high))


def is_valid_interval(interval: object) -> bool:
    """Return True if *interval* is a well-formed ``(low, high)`` interval.

    A valid interval is a two-element tuple/list of real numbers with
    ``low <= high``.
    """
    if not isinstance(interval, (tuple, list)) or len(interval) != 2:
        return False
    low, high = interval
    if not _is_number(low) or not _is_number(high):
        return False
    return bool(low <= high)


def interval_contains(interval: Interval, value: float) -> bool:
    """Return True if *value* lies within the closed interval *interval*.

    Args:
        interval: A ``(low, high)`` interval.
        value: The value to test.

    Returns:
        True if ``low <= value <= high``.

    Raises:
        TypeError: If *interval* is malformed or *value* is not a real number.
        ValueError: If *interval* is not valid (``low > high``).
    """
    if not is_valid_interval(interval):
        raise ValueError(f"invalid interval: {interval!r}")
    if not _is_number(value):
        raise TypeError(f"value must be a real number, got {type(value).__name__}")
    low, high = interval
    return low <= value <= high


def interval_overlaps(a: Interval, b: Interval) -> bool:
    """Return True if intervals *a* and *b* share at least one point.

    Args:
        a: A ``(low, high)`` interval.
        b: A ``(low, high)`` interval.

    Returns:
        True if the intervals overlap (including touching at an endpoint).

    Raises:
        ValueError: If either interval is not valid.
    """
    if not is_valid_interval(a) or not is_valid_interval(b):
        raise ValueError(f"invalid interval: {a!r} or {b!r}")
    return max(a[0], b[0]) <= min(a[1], b[1])


def interval_intersection(a: Interval, b: Interval) -> Optional[Interval]:
    """Return the overlapping portion of intervals *a* and *b*.

    Args:
        a: A ``(low, high)`` interval.
        b: A ``(low, high)`` interval.

    Returns:
        The intersection interval, or ``None`` if the intervals are disjoint.

    Raises:
        ValueError: If either interval is not valid.
    """
    if not is_valid_interval(a) or not is_valid_interval(b):
        raise ValueError(f"invalid interval: {a!r} or {b!r}")
    low = max(a[0], b[0])
    high = min(a[1], b[1])
    if low > high:
        return None
    return (low, high)


def interval_union(a: Interval, b: Interval) -> Optional[Interval]:
    """Return the smallest interval covering both *a* and *b*.

    The union is only defined when the intervals overlap or touch; disjoint
    intervals return ``None``.

    Args:
        a: A ``(low, high)`` interval.
        b: A ``(low, high)`` interval.

    Returns:
        The merged interval, or ``None`` if the intervals are disjoint.

    Raises:
        ValueError: If either interval is not valid.
    """
    if not is_valid_interval(a) or not is_valid_interval(b):
        raise ValueError(f"invalid interval: {a!r} or {b!r}")
    if not interval_overlaps(a, b):
        return None
    return (min(a[0], b[0]), max(a[1], b[1]))


def merge_intervals(intervals: list[Interval]) -> list[Interval]:
    """Merge overlapping intervals into a sorted list of disjoint intervals.

    Args:
        intervals: An iterable of ``(low, high)`` intervals.

    Returns:
        A list of disjoint, sorted intervals covering the same points.

    Raises:
        TypeError: If *intervals* is not a list.
        ValueError: If any interval is not valid.
    """
    if not isinstance(intervals, list):
        raise TypeError(f"intervals must be a list, got {type(intervals).__name__}")
    for interval in intervals:
        if not is_valid_interval(interval):
            raise ValueError(f"invalid interval: {interval!r}")
    sorted_intervals = sorted(intervals, key=lambda item: (item[0], item[1]))
    merged: list[Interval] = []
    for interval in sorted_intervals:
        if merged and interval_overlaps(merged[-1], interval):
            low = merged[-1][0]
            high = max(merged[-1][1], interval[1])
            merged[-1] = (low, high)
        else:
            merged.append(interval)
    return merged


def interval_length(interval: Interval) -> float:
    """Return the length ``high - low`` of *interval*.

    Args:
        interval: A ``(low, high)`` interval.

    Returns:
        The length of the interval as a float.

    Raises:
        ValueError: If *interval* is not valid.
    """
    if not is_valid_interval(interval):
        raise ValueError(f"invalid interval: {interval!r}")
    return float(interval[1] - interval[0])


def interval_midpoint(interval: Interval) -> float:
    """Return the midpoint ``(low + high) / 2`` of *interval*.

    Args:
        interval: A ``(low, high)`` interval.

    Returns:
        The midpoint of the interval as a float.

    Raises:
        ValueError: If *interval* is not valid.
    """
    if not is_valid_interval(interval):
        raise ValueError(f"invalid interval: {interval!r}")
    return (interval[0] + interval[1]) / 2.0


def interval_distance(a: Interval, b: Interval) -> float:
    """Return the gap between two intervals.

    For overlapping or touching intervals the distance is ``0.0``. For
    disjoint intervals it is the distance between the closest endpoints.

    Args:
        a: A ``(low, high)`` interval.
        b: A ``(low, high)`` interval.

    Returns:
        The non-negative distance between the intervals.

    Raises:
        ValueError: If either interval is not valid.
    """
    if not is_valid_interval(a) or not is_valid_interval(b):
        raise ValueError(f"invalid interval: {a!r} or {b!r}")
    if interval_overlaps(a, b):
        return 0.0
    if a[1] < b[0]:
        return float(b[0] - a[1])
    return float(a[0] - b[1])


def interval_is_subset(a: Interval, b: Interval) -> bool:
    """Return True if *a* is entirely contained within *b*.

    Args:
        a: A ``(low, high)`` interval.
        b: A ``(low, high)`` interval.

    Returns:
        True if ``b[0] <= a[0]`` and ``a[1] <= b[1]``.

    Raises:
        ValueError: If either interval is not valid.
    """
    if not is_valid_interval(a) or not is_valid_interval(b):
        raise ValueError(f"invalid interval: {a!r} or {b!r}")
    return b[0] <= a[0] and a[1] <= b[1]


def interval_shift(interval: Interval, delta: float) -> Interval:
    """Return *interval* translated by *delta*.

    Args:
        interval: A ``(low, high)`` interval.
        delta: The amount to add to both endpoints.

    Returns:
        A new ``(low + delta, high + delta)`` interval.

    Raises:
        TypeError: If *delta* is not a real number.
        ValueError: If *interval* is not valid.
    """
    if not is_valid_interval(interval):
        raise ValueError(f"invalid interval: {interval!r}")
    if not _is_number(delta):
        raise TypeError(f"delta must be a real number, got {type(delta).__name__}")
    return (interval[0] + delta, interval[1] + delta)


def interval_symmetric_difference(a: Interval, b: Interval) -> list[Interval]:
    """Return the portions of *a* and *b* that are not shared.

    The result is a sorted list of up to two disjoint intervals covering the
    points that belong to exactly one of the two input intervals. Overlapping
    or touching intervals may produce an empty list when they are identical.

    Args:
        a: A ``(low, high)`` interval.
        b: A ``(low, high)`` interval.

    Returns:
        A list of disjoint intervals (possibly empty) representing the
        symmetric difference.

    Raises:
        ValueError: If either interval is not valid.
    """
    if not is_valid_interval(a) or not is_valid_interval(b):
        raise ValueError(f"invalid interval: {a!r} or {b!r}")
    difference: list[Interval] = []
    intersection = interval_intersection(a, b)
    if intersection is None:
        # Disjoint intervals: the symmetric difference is both of them.
        difference.extend((a, b))
    else:
        low, high = intersection
        if a[0] < low:
            difference.append((a[0], low))
        if a[1] > high:
            difference.append((high, a[1]))
        if b[0] < low:
            difference.append((b[0], low))
        if b[1] > high:
            difference.append((high, b[1]))
    # Drop degenerate intervals (a shared endpoint produces zero-length slivers).
    return [interval for interval in difference if interval[0] < interval[1]]
INTERVALUTILS

# --- tests/test_interval_utils.py ---
cat > "$OUTPUT_DIR/tests/test_interval_utils.py" <<'TEST_INTERVAL_UTILS'
import unittest

from interval_utils import (
    interval_contains,
    interval_distance,
    interval_intersection,
    interval_is_subset,
    interval_length,
    interval_midpoint,
    interval_overlaps,
    interval_shift,
    interval_symmetric_difference,
    interval_union,
    is_valid_interval,
    merge_intervals,
    normalize_interval,
)


class TestNormalizeInterval(unittest.TestCase):
    def test_already_ordered(self):
        self.assertEqual(normalize_interval(1, 5), (1, 5))

    def test_swaps_endpoints(self):
        self.assertEqual(normalize_interval(5, 1), (1, 5))

    def test_equal_endpoints(self):
        self.assertEqual(normalize_interval(3, 3), (3, 3))

    def test_negative_values(self):
        self.assertEqual(normalize_interval(-5, -1), (-5, -1))
        self.assertEqual(normalize_interval(-1, -5), (-5, -1))

    def test_float_values(self):
        self.assertEqual(normalize_interval(2.5, 1.5), (1.5, 2.5))

    def test_mixed_int_float(self):
        self.assertEqual(normalize_interval(3, 1.5), (1.5, 3))

    def test_non_number_raises(self):
        with self.assertRaises(TypeError):
            normalize_interval("1", 5)
        with self.assertRaises(TypeError):
            normalize_interval(1, None)
        with self.assertRaises(TypeError):
            normalize_interval(True, 5)


class TestIsValidInterval(unittest.TestCase):
    def test_valid_tuple(self):
        self.assertTrue(is_valid_interval((1, 5)))

    def test_valid_list(self):
        self.assertTrue(is_valid_interval([1, 5]))

    def test_equal_endpoints_valid(self):
        self.assertTrue(is_valid_interval((3, 3)))

    def test_invalid_low_greater_than_high(self):
        self.assertFalse(is_valid_interval((5, 1)))

    def test_not_a_pair(self):
        self.assertFalse(is_valid_interval((1,)))
        self.assertFalse(is_valid_interval((1, 2, 3)))
        self.assertFalse(is_valid_interval("ab"))
        self.assertFalse(is_valid_interval(42))

    def test_non_number_elements(self):
        self.assertFalse(is_valid_interval(("a", "b")))
        self.assertFalse(is_valid_interval((1, "b")))
        self.assertFalse(is_valid_interval((True, 5)))

    def test_none(self):
        self.assertFalse(is_valid_interval(None))


class TestIntervalContains(unittest.TestCase):
    def test_inside(self):
        self.assertTrue(interval_contains((1, 5), 3))

    def test_at_endpoints(self):
        self.assertTrue(interval_contains((1, 5), 1))
        self.assertTrue(interval_contains((1, 5), 5))

    def test_outside(self):
        self.assertFalse(interval_contains((1, 5), 0))
        self.assertFalse(interval_contains((1, 5), 6))

    def test_degenerate_interval(self):
        self.assertTrue(interval_contains((3, 3), 3))
        self.assertFalse(interval_contains((3, 3), 4))

    def test_float_value(self):
        self.assertTrue(interval_contains((1.5, 2.5), 2.0))

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            interval_contains((5, 1), 3)

    def test_non_number_value_raises(self):
        with self.assertRaises(TypeError):
            interval_contains((1, 5), "x")


class TestIntervalOverlaps(unittest.TestCase):
    def test_overlapping(self):
        self.assertTrue(interval_overlaps((1, 5), (4, 8)))

    def test_touching_endpoints(self):
        self.assertTrue(interval_overlaps((1, 5), (5, 8)))

    def test_disjoint(self):
        self.assertFalse(interval_overlaps((1, 3), (4, 8)))

    def test_one_inside_other(self):
        self.assertTrue(interval_overlaps((1, 10), (4, 6)))

    def test_identical(self):
        self.assertTrue(interval_overlaps((2, 4), (2, 4)))

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            interval_overlaps((5, 1), (2, 4))


class TestIntervalIntersection(unittest.TestCase):
    def test_partial_overlap(self):
        self.assertEqual(interval_intersection((1, 5), (4, 8)), (4, 5))

    def test_touching(self):
        self.assertEqual(interval_intersection((1, 5), (5, 8)), (5, 5))

    def test_disjoint(self):
        self.assertIsNone(interval_intersection((1, 3), (4, 8)))

    def test_one_inside_other(self):
        self.assertEqual(interval_intersection((1, 10), (4, 6)), (4, 6))

    def test_identical(self):
        self.assertEqual(interval_intersection((2, 4), (2, 4)), (2, 4))

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            interval_intersection((5, 1), (2, 4))


class TestIntervalUnion(unittest.TestCase):
    def test_overlapping_merges(self):
        self.assertEqual(interval_union((1, 5), (4, 8)), (1, 8))

    def test_touching_merges(self):
        self.assertEqual(interval_union((1, 5), (5, 8)), (1, 8))

    def test_disjoint_returns_none(self):
        self.assertIsNone(interval_union((1, 3), (4, 8)))

    def test_one_inside_other(self):
        self.assertEqual(interval_union((1, 10), (4, 6)), (1, 10))

    def test_identical(self):
        self.assertEqual(interval_union((2, 4), (2, 4)), (2, 4))

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            interval_union((5, 1), (2, 4))


class TestMergeIntervals(unittest.TestCase):
    def test_disjoint_stays_disjoint(self):
        self.assertEqual(merge_intervals([(1, 3), (5, 8)]), [(1, 3), (5, 8)])

    def test_overlapping_merges(self):
        self.assertEqual(merge_intervals([(1, 5), (4, 8)]), [(1, 8)])

    def test_touching_merges(self):
        self.assertEqual(merge_intervals([(1, 5), (5, 8)]), [(1, 8)])

    def test_unsorted_input(self):
        self.assertEqual(merge_intervals([(5, 8), (1, 3)]), [(1, 3), (5, 8)])

    def test_chain_merge(self):
        self.assertEqual(merge_intervals([(1, 3), (2, 6), (5, 8)]), [(1, 8)])

    def test_empty_list(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single_interval(self):
        self.assertEqual(merge_intervals([(2, 4)]), [(2, 4)])

    def test_non_list_raises(self):
        with self.assertRaises(TypeError):
            merge_intervals((1, 3))  # type: ignore[arg-type]

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            merge_intervals([(5, 1)])


class TestIntervalLength(unittest.TestCase):
    def test_positive_length(self):
        self.assertEqual(interval_length((1, 5)), 4.0)

    def test_zero_length(self):
        self.assertEqual(interval_length((3, 3)), 0.0)

    def test_float_length(self):
        self.assertEqual(interval_length((1.5, 3.5)), 2.0)

    def test_negative_interval(self):
        self.assertEqual(interval_length((-5, -1)), 4.0)

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            interval_length((5, 1))


class TestIntervalMidpoint(unittest.TestCase):
    def test_whole_number(self):
        self.assertEqual(interval_midpoint((1, 5)), 3.0)

    def test_fractional(self):
        self.assertEqual(interval_midpoint((1, 4)), 2.5)

    def test_degenerate_interval(self):
        self.assertEqual(interval_midpoint((3, 3)), 3.0)

    def test_negative_interval(self):
        self.assertEqual(interval_midpoint((-5, -1)), -3.0)

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            interval_midpoint((5, 1))


class TestIntervalDistance(unittest.TestCase):
    def test_overlapping_is_zero(self):
        self.assertEqual(interval_distance((1, 5), (4, 8)), 0.0)

    def test_touching_is_zero(self):
        self.assertEqual(interval_distance((1, 5), (5, 8)), 0.0)

    def test_disjoint_a_before_b(self):
        self.assertEqual(interval_distance((1, 3), (5, 8)), 2.0)

    def test_disjoint_b_before_a(self):
        self.assertEqual(interval_distance((5, 8), (1, 3)), 2.0)

    def test_float_distance(self):
        self.assertEqual(interval_distance((1.0, 2.0), (3.5, 5.0)), 1.5)

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            interval_distance((5, 1), (2, 4))


class TestIntervalIsSubset(unittest.TestCase):
    def test_a_inside_b(self):
        self.assertTrue(interval_is_subset((2, 4), (1, 5)))

    def test_a_touches_b_endpoints(self):
        self.assertTrue(interval_is_subset((1, 5), (1, 5)))

    def test_a_extends_past_b(self):
        self.assertFalse(interval_is_subset((0, 6), (1, 5)))

    def test_a_outside_b(self):
        self.assertFalse(interval_is_subset((6, 8), (1, 5)))

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            interval_is_subset((5, 1), (1, 5))


class TestIntervalShift(unittest.TestCase):
    def test_shift_positive(self):
        self.assertEqual(interval_shift((1, 5), 2), (3, 7))

    def test_shift_negative(self):
        self.assertEqual(interval_shift((1, 5), -3), (-2, 2))

    def test_shift_float(self):
        self.assertEqual(interval_shift((1.5, 3.5), 0.5), (2.0, 4.0))

    def test_shift_zero(self):
        self.assertEqual(interval_shift((1, 5), 0), (1, 5))

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            interval_shift((5, 1), 2)

    def test_non_number_delta_raises(self):
        with self.assertRaises(TypeError):
            interval_shift((1, 5), "2")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            interval_shift((1, 5), True)  # type: ignore[arg-type]


class TestIntervalSymmetricDifference(unittest.TestCase):
    def test_disjoint_returns_both(self):
        self.assertEqual(
            interval_symmetric_difference((1, 3), (5, 8)),
            [(1, 3), (5, 8)],
        )

    def test_identical_returns_empty(self):
        self.assertEqual(interval_symmetric_difference((1, 5), (1, 5)), [])

    def test_partial_overlap(self):
        self.assertEqual(
            interval_symmetric_difference((1, 5), (4, 8)),
            [(1, 4), (5, 8)],
        )

    def test_one_inside_other(self):
        self.assertEqual(
            interval_symmetric_difference((2, 4), (1, 5)),
            [(1, 2), (4, 5)],
        )

    def test_touching_intervals(self):
        self.assertEqual(
            interval_symmetric_difference((1, 5), (5, 8)),
            [(1, 5), (5, 8)],
        )

    def test_invalid_interval_raises(self):
        with self.assertRaises(ValueError):
            interval_symmetric_difference((5, 1), (2, 4))


if __name__ == "__main__":
    unittest.main()
TEST_INTERVAL_UTILS



# --- CHANGELOG.md ---
cat > "$OUTPUT_DIR/CHANGELOG.md" <<'CHANGELOG'
## Unreleased

- Added `indent_lines(text, prefix="    ", *, skip_blank=False)` to `prompt_utils.py` as a companion to `truncate_lines` and `wrap_prompt`: it prefixes every line of *text* with *prefix*, leaving blank lines untouched when *skip_blank* is True. It validates that *text* and *prefix* are strings and *skip_blank* is a bool, raising `TypeError` otherwise. Added `TestIndentLines` to `tests/test_prompt_utils.py` covering the default prefix, a custom prefix, blank-line handling with both modes, the empty-string case, and the `TypeError` paths. Updated the `prompt_utils` module prose section of `README.md`. Synchronized `prompt_utils.py`, `tests/test_prompt_utils.py`, `README.md`, and this CHANGELOG into the embedded copies of `scaffold.sh` with `make refresh-scaffold`; `python tools/refresh_scaffold.py --check` reports all embedded copies in sync.

- Added `truncate_lines` to `prompt_utils.py`.
- Added `is_pangram(s)` to `strings.py` with a typed signature, `__all__` export, a Google-style docstring, and `TypeError` validation for non-string arguments; it returns `True` when *s* contains every letter of the English alphabet at least once (case-insensitive, ignoring non-alphabetic characters), `False` otherwise (including for the empty string). Added `TestIsPangram` to `tests/test_strings.py`. Updated the `strings` module section of `README.md`. Synchronized `strings.py`, `tests/test_strings.py`, `README.md`, and this CHANGELOG into the embedded copies of `scaffold.sh` with `make refresh-scaffold`; `python tools/refresh_scaffold.py --check` reports all embedded copies in sync.

- Added `decrement_version(version, part="patch")` to `version_utils.py` as the symmetric counterpart to `bump_version`: it validates that *version* is a string and *part* is a string, is case-insensitive on the recognized component names (`"major"`, `"minor"`, `"patch"`), and dispatches to the existing `decrement_major`/`decrement_minor`/`decrement_patch` helpers, raising `ValueError` for unrecognized parts or when the chosen component is already 0. Also exported `decrement_major`, `decrement_minor`, and `decrement_patch` (they were previously defined but absent from `__all__`), and added the `decrement` alias. Added `TestDecrementMajor`, `TestDecrementMinor`, `TestDecrementPatch`, and `TestDecrementVersion` to `tests/test_version_utils.py`. Updated the `version_utils` module tree entry and prose section of `README.md`. Synchronized `version_utils.py`, `tests/test_version_utils.py`, `README.md`, and this CHANGELOG into the embedded copies of `scaffold.sh` with `make refresh-scaffold`; `python tools/refresh_scaffold.py --check` reports all embedded copies in sync.

- Added `is_compatible` to `version_utils.py`.

- Added `trimmed_mean(numbers, trim_count=0)` to `stats.py` with a typed signature, `__all__` export, a Google-style docstring, and `TypeError`/`ValueError` validation; it discards *trim_count* values from each end of the sorted list and returns the arithmetic mean of the remaining interior values, raising `ValueError` for a negative *trim_count* or one that is at least half the list length (so at least one value remains). It defaults to *trim_count* 0, in which case it matches `mean`. Added `TestTrimmedMean` to `tests/test_stats.py`. Updated the `stats` module section of `README.md`. Synchronized `stats.py`, `tests/test_stats.py`, `README.md`, and this CHANGELOG into the embedded copies of `scaffold.sh` with `make refresh-scaffold`; `python tools/refresh_scaffold.py --check` reports all embedded copies in sync.

- Added `multimode(numbers)` to `stats.py` with a typed signature, `__all__` export, a Google-style docstring, and `TypeError`/`ValueError` validation; it returns every value that shares the highest frequency in the order each value first appears (a companion to `mode`, like `statistics.multimode`). Added `TestMultimode` to `tests/test_stats.py`. Updated the `stats` module section of `README.md`. Synchronized `stats.py`, `tests/test_stats.py`, and `README.md` into the embedded copies of `scaffold.sh` with `make refresh-scaffold`; `python tools/refresh_scaffold.py --check` reports all embedded copies in sync.

