    def test_composite_reexports_match_ctypes(self):
        self.assertIs(Structure, ctypes.Structure)
        self.assertIs(Union, ctypes.Union)
        self.assertIs(POINTER, ctypes.POINTER)
        self.assertIs(Array, ctypes.Array)
