    if not isinstance(m, (list, tuple)):
        raise TypeError(f"commonprefix() argument must be a sequence, not {type(m).__name__}")
    for item in m:
        _check_path_like(item, "path")
    return cast(str, _posixpath.commonprefix(cast(Any, list(m))))


