"""Tests for number_utils module."""

import unittest

from number_utils import (
    clamp,
    format_number,
    is_between,
    is_even,
    is_finite,
    is_infinite,
    is_integer,
    is_nan,
    is_negative,
    is_non_negative,
    is_non_positive,
    is_odd,
    is_perfect_cube,
    is_perfect_square,
    is_positive,
