# --- queue_utils.py ---
cat > "$OUTPUT_DIR/queue_utils.py" <<'QUEUE_UTILS'
"""Utility helpers for queue operations."""

from collections import deque


class Queue:
    """A simple FIFO queue."""

    def __init__(self, items=None):
        self._data = deque(items or [])

    def enqueue(self, value):
        self._data.append(value)

    def dequeue(self):
        if not self._data:
            raise IndexError("dequeue from empty queue")
        return self._data.popleft()

    def peek(self):
        if not self._data:
            raise IndexError("peek from empty queue")
        return self._data[0]

    def is_empty(self):
        return not self._data

    def size(self):
        return len(self._data)

    def clear(self):
        self._data.clear()

    def to_list(self):
        return list(self._data)

    @classmethod
    def from_list(cls, items):
        return cls(items)


def create(items=None):
    return Queue(items)


def enqueue(queue, value):
    queue.enqueue(value)
    return queue


def dequeue(queue):
    return queue.dequeue()


def peek(queue):
    return queue.peek()


def is_empty(queue):
    return queue.is_empty()


def size(queue):
    return queue.size()
QUEUE_UTILS

# --- tests/test_queue_utils.py ---
cat > "$OUTPUT_DIR/tests/test_queue_utils.py" <<'TEST_QUEUE_UTILS'
import unittest

from queue_utils import Queue, create, dequeue, enqueue, is_empty, peek, size


class TestQueueUtils(unittest.TestCase):
    def test_basic(self):
        q = create([1, 2])
        self.assertFalse(is_empty(q))
        self.assertEqual(size(q), 2)
        self.assertEqual(peek(q), 1)
        self.assertEqual(dequeue(q), 1)
        self.assertEqual(dequeue(q), 2)
        self.assertTrue(is_empty(q))

    def test_enqueue(self):
        q = Queue()
        enqueue(q, 5)
        self.assertEqual(q.to_list(), [5])

    def test_errors(self):
        q = Queue()
        with self.assertRaises(IndexError):
            q.dequeue()
        with self.assertRaises(IndexError):
            q.peek()


if __name__ == "__main__":
    unittest.main()
