cat > "$OUTPUT_DIR/stat_utils.py" <<'STAT_UTILS'
"""Utilities for file type and mode inspection (wrapping :mod:`stat` and :func:`os.stat`)."""

import os
import stat as _stat
from typing import Any


def file_mode(path: str | os.PathLike[str]) -> int:
    """Return the permission bits of *path* (the low 12 bits of ``st_mode``).

    Args:
        path: Filesystem path to inspect.

    Returns:
        The file permission bits (e.g. ``0o644``).
    """
    return _stat.S_IMODE(os.stat(path).st_mode)


def file_type(path: str | os.PathLike[str]) -> int:
    """Return the file type bits of *path*.

    Args:
        path: Filesystem path to inspect.

    Returns:
        The file type bits (e.g. ``stat.S_IFREG``).
    """
    return _stat.S_IFMT(os.stat(path).st_mode)


def is_directory(path: str | os.PathLike[str]) -> bool:
    """Return True if *path* is a directory."""
    return _stat.S_ISDIR(os.stat(path).st_mode)


def is_regular_file(path: str | os.PathLike[str]) -> bool:
    """Return True if *path* is a regular file."""
    return _stat.S_ISREG(os.stat(path).st_mode)


def is_symlink(path: str | os.PathLike[str]) -> bool:
    """Return True if *path* is a symbolic link."""
    return _stat.S_ISLNK(os.lstat(path).st_mode)


def is_socket(path: str | os.PathLike[str]) -> bool:
    """Return True if *path* is a socket."""
    return _stat.S_ISSOCK(os.stat(path).st_mode)


def is_fifo(path: str | os.PathLike[str]) -> bool:
    """Return True if *path* is a FIFO (named pipe)."""
    return _stat.S_ISFIFO(os.stat(path).st_mode)


def is_device(path: str | os.PathLike[str]) -> bool:
    """Return True if *path* is a character or block device."""
    st_mode = os.stat(path).st_mode
    return _stat.S_ISCHR(st_mode) or _stat.S_ISBLK(st_mode)


def filemode(path: str | os.PathLike[str]) -> str:
    """Return a string like ``-rwxr-xr-x`` describing *path*'s permissions.

    Args:
        path: Filesystem path to inspect.

    Returns:
        The symbolic file mode string.
    """
    return _stat.filemode(os.stat(path).st_mode)


def stat_info(path: str | os.PathLike[str]) -> dict[str, Any]:
    """Return a dictionary of the :func:`os.stat` result fields for *path*.

    Args:
        path: Filesystem path to inspect.

    Returns:
        A mapping of stat result field names to their values.
    """
    result = os.stat(path)
    return {
        "mode": result.st_mode,
        "ino": result.st_ino,
        "dev": result.st_dev,
        "nlink": result.st_nlink,
        "uid": result.st_uid,
        "gid": result.st_gid,
        "size": result.st_size,
        "atime": result.st_atime,
        "mtime": result.st_mtime,
        "ctime": result.st_ctime,
    }
STAT_UTILS

# --- tests/test_stat_utils.py ---
cat > "$OUTPUT_DIR/tests/test_stat_utils.py" <<'TEST_STAT_UTILS'
import os
import stat as _stat
import tempfile
import unittest

from stat_utils import (
    file_mode,
    file_type,
    filemode,
    is_device,
    is_directory,
    is_fifo,
    is_regular_file,
    is_socket,
    is_symlink,
    stat_info,
)


class TestStatUtils(unittest.TestCase):
    def setUp(self) -> None:
        self.tmpdir = tempfile.mkdtemp(prefix="stat-utils-test-")
        self.file_path = os.path.join(self.tmpdir, "sample.txt")
        with open(self.file_path, "w", encoding="utf-8") as handle:
            handle.write("stat-utils sample data\n")
        self.dir_path = os.path.join(self.tmpdir, "subdir")
        os.mkdir(self.dir_path)

    def tearDown(self) -> None:
        for name in ("sample.txt", "subdir"):
            path = os.path.join(self.tmpdir, name)
            if os.path.isdir(path) and not os.path.islink(path):
                os.rmdir(path)
            elif os.path.exists(path):
                os.remove(path)
        os.rmdir(self.tmpdir)

    def test_file_mode_regular_file(self):
        mode = file_mode(self.file_path)
        self.assertIsInstance(mode, int)
        self.assertTrue(mode & 0o600)

    def test_file_mode_directory(self):
        mode = file_mode(self.dir_path)
        self.assertIsInstance(mode, int)
        self.assertTrue(_stat.S_ISDIR(mode) or _stat.S_ISDIR(os.stat(self.dir_path).st_mode))

    def test_file_type(self):
        self.assertEqual(file_type(self.file_path), _stat.S_IFREG)
        self.assertEqual(file_type(self.dir_path), _stat.S_IFDIR)

    def test_is_directory(self):
        self.assertTrue(is_directory(self.dir_path))
        self.assertFalse(is_directory(self.file_path))

    def test_is_regular_file(self):
        self.assertTrue(is_regular_file(self.file_path))
        self.assertFalse(is_regular_file(self.dir_path))

    def test_is_symlink(self):
        self.assertFalse(is_symlink(self.file_path))
        link_path = os.path.join(self.tmpdir, "link.txt")
        os.symlink(self.file_path, link_path)
        try:
            self.assertTrue(is_symlink(link_path))
            self.assertTrue(is_regular_file(link_path))
        finally:
            os.remove(link_path)

    def test_is_socket_and_fifo_and_device_false(self):
        self.assertFalse(is_socket(self.file_path))
        self.assertFalse(is_fifo(self.file_path))
        self.assertFalse(is_device(self.file_path))

    def test_filemode_string(self):
        result = filemode(self.file_path)
        self.assertIsInstance(result, str)
        self.assertEqual(len(result), 10)
        self.assertTrue(result.startswith("-"))

    def test_stat_info_keys(self):
        info = stat_info(self.file_path)
        expected = {
            "mode",
            "ino",
            "dev",
            "nlink",
            "uid",
            "gid",
            "size",
            "atime",
            "mtime",
            "ctime",
        }
        self.assertEqual(set(info.keys()), expected)
        self.assertGreater(info["size"], 0)

    def test_stat_info_rounds_trip_with_os_stat(self):
        info = stat_info(self.file_path)
        direct = os.stat(self.file_path)
        self.assertEqual(info["mode"], direct.st_mode)
        self.assertEqual(info["size"], direct.st_size)
        self.assertEqual(info["mtime"], direct.st_mtime)


if __name__ == "__main__":
    unittest.main()
TEST_STAT_UTILS

# --- stringprep_utils.py ---
cat > "$OUTPUT_DIR/stringprep_utils.py" <<'STRINGPREP_UTILS'
"""String preparation utilities wrapping the standard library :mod:`stringprep` module.

The :mod:`stringprep` module exposes the tables of RFC 3454, the "String
Preparation" framework that the internationalized domain names of RFC 3491
are built on.  A table is either a set, which answers whether a character
belongs to it, or a mapping, which turns a character into another one.

This wrapper validates every argument before the standard library is reached,
so a caller gets a clear :class:`TypeError` or :class:`ValueError` instead of
an opaque failure from the C layer.  It also adds the conveniences that the
standard library leaves to the caller: the tables are addressed by their name
such as ``"b1"``, the prohibited output of RFC 3454 is summarized by
:func:`is_prohibited`, and :func:`map_text` performs the mapping step of the
framework in one call.

The module is pure computation, so it works on every platform and never
touches the file system, the network, or a process.
"""

from __future__ import annotations

import stringprep as _stringprep
from types import MappingProxyType
from typing import Callable, Mapping

__all__: list[str] = [
    "MAP_TABLES",
    "TABLES",
    "find_problems",
    "in_table",
    "is_allowed",
    "is_bidi_allowed",
    "is_mapped_to_nothing",
    "is_preparable",
    "is_prohibited",
    "is_unassigned",
    "map_table",
    "map_table_names",
    "map_text",
    "table_names",
]


#: The set tables of RFC 3454, addressed by their name.
TABLES: Mapping[str, Callable[[str], bool]] = MappingProxyType(
    {
        "a1": _stringprep.in_table_a1,
        "b1": _stringprep.in_table_b1,
        "c11": _stringprep.in_table_c11,
        "c12": _stringprep.in_table_c12,
        "c11_c12": _stringprep.in_table_c11_c12,
        "c21": _stringprep.in_table_c21,
        "c22": _stringprep.in_table_c22,
        "c21_c22": _stringprep.in_table_c21_c22,
        "c3": _stringprep.in_table_c3,
        "c4": _stringprep.in_table_c4,
        "c5": _stringprep.in_table_c5,
        "c6": _stringprep.in_table_c6,
        "c7": _stringprep.in_table_c7,
        "c8": _stringprep.in_table_c8,
        "c9": _stringprep.in_table_c9,
        "d1": _stringprep.in_table_d1,
        "d2": _stringprep.in_table_d2,
    }
)

#: The mapping tables of RFC 3454, addressed by their name.
MAP_TABLES: Mapping[str, Callable[[str], str]] = MappingProxyType(
    {
        "b2": _stringprep.map_table_b2,
        "b3": _stringprep.map_table_b3,
    }
)

# The tables of the prohibited output of RFC 3454.  Table C.1.1, the plain
# space, is not one of them: it is allowed in a stored string.
_PROHIBITED_TABLES: tuple[str, ...] = (
    "c12",
    "c21",
    "c22",
    "c3",
    "c4",
    "c5",
    "c6",
    "c7",
    "c8",
    "c9",
)


def _character(value: str, name: str = "character") -> str:
    """Return *value* after checking that it is a single character.

    Args:
        value: The character to check.
        name: The name of the argument, used in the error messages.

    Raises:
        TypeError: If *value* is not a string.
        ValueError: If *value* is empty or holds more than one character.
    """
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a str, got {type(value).__name__}")
    if len(value) != 1:
        raise ValueError(f"{name} must be a single character, got {len(value)}")
    return value


def table_names() -> tuple[str, ...]:
    """Return the names of the set tables of RFC 3454.

    The names are the ones the framework uses: ``"a1"`` for the unassigned
    code points, ``"b1"`` for the characters that are commonly mapped to
    nothing, ``"c11"`` up to ``"c9"`` for the prohibited output, and ``"d1"``
    and ``"d2"`` for the bidirectional characters.
    """
    return tuple(sorted(TABLES))


def map_table_names() -> tuple[str, ...]:
    """Return the names of the mapping tables of RFC 3454.

    The names are the ones the framework uses: ``"b2"`` for the case folding
    with the compatibility decomposition and ``"b3"`` for the plain case
    folding.
    """
    return tuple(sorted(MAP_TABLES))


def in_table(name: str, character: str) -> bool:
    """Report whether a character belongs to a set table of RFC 3454.

    Args:
        name: The name of the table, such as ``"b1"``.
        character: The character to look for.

    Returns:
        ``True`` when the character belongs to the table.

    Raises:
        TypeError: If *name* or *character* is not a string.
        ValueError: If *name* is not the name of a set table, or if
            *character* is not a single character.
    """
    if not isinstance(name, str):
        raise TypeError(f"name must be a str, got {type(name).__name__}")
    table = TABLES.get(name)
    if table is None:
        raise ValueError(f"unknown table: {name}")
    return bool(table(_character(character)))


def map_table(name: str, character: str) -> str:
    """Map a character with a mapping table of RFC 3454.

    Args:
        name: The name of the table, such as ``"b2"``.
        character: The character to map.

    Returns:
        The mapped character, which may be empty for a character that is
        mapped to nothing.

    Raises:
        TypeError: If *name* or *character* is not a string.
        ValueError: If *name* is not the name of a mapping table, or if
            *character* is not a single character.
    """
    if not isinstance(name, str):
        raise TypeError(f"name must be a str, got {type(name).__name__}")
    table = MAP_TABLES.get(name)
    if table is None:
        raise ValueError(f"unknown mapping table: {name}")
    return str(table(_character(character)))


def is_unassigned(character: str) -> bool:
    """Report whether a character is an unassigned code point.

    The unassigned code points are the ones of table A.1 of RFC 3454.

    Raises:
        TypeError: If *character* is not a string.
        ValueError: If *character* is not a single character.
    """
    return bool(_stringprep.in_table_a1(_character(character)))


def is_mapped_to_nothing(character: str) -> bool:
    """Report whether a character is commonly mapped to nothing.

    The characters of table B.1 of RFC 3454, such as the soft hyphen, are
    removed while a string is prepared.

    Raises:
        TypeError: If *character* is not a string.
        ValueError: If *character* is not a single character.
    """
    return bool(_stringprep.in_table_b1(_character(character)))


def is_prohibited(character: str) -> bool:
    """Report whether a character belongs to the prohibited output.

    The prohibited output of RFC 3454 gathers the tables C.1.2 up to C.9, so
    the non-ASCII spaces, the control characters, the private use characters,
    the non-character code points, the surrogates, and the characters that
    are inappropriate for plain text or for a canonical representation.

    Raises:
        TypeError: If *character* is not a string.
        ValueError: If *character* is not a single character.
    """
    _character(character)
    return any(TABLES[name](character) for name in _PROHIBITED_TABLES)


def is_allowed(character: str) -> bool:
    """Report whether a character may be stored in a prepared string.

    A character is allowed when it is neither an unassigned code point nor
    part of the prohibited output of RFC 3454.  The characters that are
    commonly mapped to nothing stay allowed, because they are removed while
    the string is mapped rather than rejected.

    Raises:
        TypeError: If *character* is not a string.
        ValueError: If *character* is not a single character.
    """
    _character(character)
    return not is_unassigned(character) and not is_prohibited(character)


def is_bidi_allowed(character: str) -> bool:
    """Report whether a character may appear in a bidirectional name.

    The characters of the tables D.1 and D.2 of RFC 3454, the right-to-left
    and the left-to-right characters, may appear in a name that mixes the two
    directions.

    Raises:
        TypeError: If *character* is not a string.
        ValueError: If *character* is not a single character.
    """
    _character(character)
    return bool(_stringprep.in_table_d1(character) or _stringprep.in_table_d2(character))


def map_text(text: str) -> str:
    """Map a string with the mapping step of RFC 3454.

    The characters of table B.1 are removed, the rest is mapped with the
    table B.2, and the result is mapped with the table B.3.

    Args:
        text: The string to map.

    Returns:
        The mapped string.

    Raises:
        TypeError: If *text* is not a string.
    """
    if not isinstance(text, str):
        raise TypeError(f"text must be a str, got {type(text).__name__}")
    removed = "".join(char for char in text if not _stringprep.in_table_b1(char))
    folded = "".join(_stringprep.map_table_b2(char) for char in removed)
    return "".join(_stringprep.map_table_b3(char) for char in folded)


def find_problems(text: str) -> list[str]:
    """Return the problems of a string that holds the prohibited output.

    Every character that is an unassigned code point or that belongs to the
    prohibited output of RFC 3454 is reported, so a caller can show why a
    string cannot be stored.

    Args:
        text: The string to inspect.

    Returns:
        One message per offending character, in the order of the string.

    Raises:
        TypeError: If *text* is not a string.
    """
    if not isinstance(text, str):
        raise TypeError(f"text must be a str, got {type(text).__name__}")
    problems: list[str] = []
    for char in text:
        if is_unassigned(char):
            problems.append(f"unassigned code point U+{ord(char):04X}")
        elif is_prohibited(char):
            problems.append(f"prohibited code point U+{ord(char):04X}")
    return problems


def is_preparable(text: str) -> bool:
    """Report whether a string may be prepared and stored.

    Args:
        text: The string to inspect.

    Returns:
        ``True`` when the string holds no unassigned code point and no part
        of the prohibited output of RFC 3454.

    Raises:
        TypeError: If *text* is not a string.
    """
    if not isinstance(text, str):
        raise TypeError(f"text must be a str, got {type(text).__name__}")
    return not find_problems(text)
STRINGPREP_UTILS

# --- tests/test_stringprep_utils.py ---
cat > "$OUTPUT_DIR/tests/test_stringprep_utils.py" <<'TEST_STRINGPREP_UTILS'
"""Tests for stringprep_utils."""

import unittest

import stringprep_utils
from stringprep_utils import (
    MAP_TABLES,
    TABLES,
    find_problems,
    in_table,
    is_allowed,
    is_bidi_allowed,
    is_mapped_to_nothing,
    is_preparable,
    is_prohibited,
    is_unassigned,
    map_table,
    map_table_names,
    map_text,
    table_names,
)


class TestStringprepUtils(unittest.TestCase):
    """Verify the string preparation helpers of the wrapper."""

    def test_the_tables_are_read_only(self):
        with self.assertRaises(TypeError):
            TABLES["a2"] = lambda char: True  # type: ignore[index]
        with self.assertRaises(TypeError):
            MAP_TABLES["b4"] = lambda char: char  # type: ignore[index]

    def test_table_names(self):
        names = table_names()
        self.assertEqual(names, tuple(sorted(names)))
        self.assertIn("a1", names)
        self.assertIn("b1", names)
        self.assertIn("c21", names)
        self.assertIn("d1", names)
        self.assertEqual(len(names), len(TABLES))

    def test_map_table_names(self):
        names = map_table_names()
        self.assertEqual(names, ("b2", "b3"))
        self.assertEqual(len(names), len(MAP_TABLES))

    def test_in_table_finds_a_member(self):
        self.assertTrue(in_table("b1", "\u00ad"))
        self.assertFalse(in_table("b1", "a"))
        self.assertTrue(in_table("a1", "\u0378"))
        self.assertTrue(in_table("c21", "\n"))
        self.assertTrue(in_table("d1", "\u05d0"))

    def test_in_table_validates_its_arguments(self):
        with self.assertRaises(TypeError):
            in_table(1, "a")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            in_table("b1", 1)  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            in_table("b1", "")
        with self.assertRaises(ValueError):
            in_table("b1", "ab")
        with self.assertRaises(ValueError):
            in_table("z9", "a")

    def test_map_table_maps_a_character(self):
        self.assertEqual(map_table("b3", "A"), "a")
        self.assertEqual(map_table("b2", "A"), "a")
        self.assertEqual(map_table("b2", "\u00df"), "ss")

    def test_map_table_validates_its_arguments(self):
        with self.assertRaises(TypeError):
            map_table(1, "a")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            map_table("b2", 1)  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            map_table("b2", "")
        with self.assertRaises(ValueError):
            map_table("b2", "ab")
        with self.assertRaises(ValueError):
            map_table("b1", "a")

    def test_is_unassigned(self):
        self.assertTrue(is_unassigned("\u0378"))
        self.assertFalse(is_unassigned("a"))
        self.assertFalse(is_unassigned("\u00e9"))

    def test_is_mapped_to_nothing(self):
        self.assertTrue(is_mapped_to_nothing("\u00ad"))
        self.assertTrue(is_mapped_to_nothing("\u200b"))
        self.assertFalse(is_mapped_to_nothing("a"))

    def test_is_prohibited(self):
        self.assertTrue(is_prohibited("\n"))
        self.assertTrue(is_prohibited("\u0085"))
        self.assertTrue(is_prohibited("\u00a0"))
        self.assertTrue(is_prohibited("\ue000"))
        self.assertTrue(is_prohibited("\uffff"))
        self.assertTrue(is_prohibited("\ud800"))
        self.assertTrue(is_prohibited("\ufffd"))
        self.assertTrue(is_prohibited("\u2ff0"))
        self.assertTrue(is_prohibited("\u200e"))
        self.assertTrue(is_prohibited("\U000e0001"))

    def test_is_prohibited_keeps_the_plain_space(self):
        self.assertFalse(is_prohibited(" "))
        self.assertFalse(is_prohibited("a"))
        self.assertFalse(is_prohibited("1"))

    def test_is_allowed(self):
        self.assertTrue(is_allowed("a"))
        self.assertTrue(is_allowed(" "))
        self.assertTrue(is_allowed("1"))
        self.assertFalse(is_allowed("\u0378"))
        self.assertFalse(is_allowed("\n"))
        self.assertFalse(is_allowed("\ue000"))

    def test_is_bidi_allowed(self):
        self.assertTrue(is_bidi_allowed("a"))
        self.assertTrue(is_bidi_allowed("\u05d0"))
        self.assertFalse(is_bidi_allowed("1"))

    def test_map_text_removes_the_characters_mapped_to_nothing(self):
        self.assertEqual(map_text("a\u00adb"), "ab")
        self.assertEqual(map_text("a\u200bb"), "ab")

    def test_map_text_folds_the_case(self):
        self.assertEqual(map_text("ABC"), "abc")
        self.assertEqual(map_text(""), "")
        self.assertEqual(map_text("\u00df"), "ss")

    def test_find_problems_reports_the_offending_characters(self):
        self.assertEqual(find_problems("example.com"), [])
        problems = find_problems("a\u0378\n")
        self.assertEqual(len(problems), 2)
        self.assertIn("U+0378", problems[0])
        self.assertIn("unassigned", problems[0])
        self.assertIn("U+000A", problems[1])
        self.assertIn("prohibited", problems[1])

    def test_is_preparable(self):
        self.assertTrue(is_preparable("example.com"))
        self.assertTrue(is_preparable(""))
        self.assertFalse(is_preparable("a\nb"))
        self.assertFalse(is_preparable("a\u0378"))

    def test_the_helpers_validate_their_arguments(self):
        with self.assertRaises(TypeError):
            is_unassigned(1)  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            is_unassigned("")
        with self.assertRaises(TypeError):
            is_mapped_to_nothing(1)  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            is_mapped_to_nothing("ab")
        with self.assertRaises(TypeError):
            is_prohibited(1)  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            is_prohibited("ab")
        with self.assertRaises(TypeError):
            is_allowed(1)  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            is_allowed("")
        with self.assertRaises(TypeError):
            is_bidi_allowed(1)  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            is_bidi_allowed("ab")
        with self.assertRaises(TypeError):
            map_text(1)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            find_problems(1)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            is_preparable(1)  # type: ignore[arg-type]

    def test_all_is_sorted_and_unique(self):
        self.assertIsNotNone(stringprep_utils.__all__)
        self.assertEqual(
            len(stringprep_utils.__all__), len(set(stringprep_utils.__all__))
        )
        self.assertEqual(stringprep_utils.__all__, sorted(stringprep_utils.__all__))
        for name in stringprep_utils.__all__:
            self.assertTrue(hasattr(stringprep_utils, name), name)


if __name__ == "__main__":
    unittest.main()
TEST_STRINGPREP_UTILS

# --- symtable_utils.py ---
cat > "$OUTPUT_DIR/symtable_utils.py" <<'SYMTABLE_UTILS'
"""Symbol table utilities (wrapping :mod:`symtable`).

The :mod:`symtable` module exposes the compiler's view of a program: the
nested scope structure of a module, function, or class, together with the
symbols each scope binds and how they are used. This wrapper offers a small,
validated surface over that information so callers can inspect scopes, resolve
symbols, and collect free variables or globals without handling the raw
standard library objects.
"""

from __future__ import annotations

import importlib.util
import symtable as _symtable
from pathlib import Path
from typing import Any, Callable, Dict, Iterator, List, Optional, Tuple

__all__ = [
    "COMPILE_TYPES",
    "assigned_names",
    "build_symbol_table",
    "child_scopes",
    "describe_scope",
    "find_scope",
    "free_variables",
    "global_names",
    "imported_names",
    "iter_scopes",
    "local_names",
    "lookup_symbol_table",
    "namespace_names",
    "nonlocal_names",
    "parameter_names",
    "referenced_names",
    "scope_identifiers",
    "scope_type",
    "symbol_flags",
    "symbol_info",
]

COMPILE_TYPES = ("exec", "eval", "single")

_SYMBOL_FLAGS = (
    "is_global",
    "is_local",
    "is_free",
    "is_nonlocal",
    "is_parameter",
    "is_imported",
    "is_assigned",
    "is_referenced",
    "is_namespace",
    "is_declared_global",
    "is_declared_nonlocal",
)


def _require_text(value: object, name: str) -> str:
    """Return *value* when it is a string, otherwise raise ``TypeError``."""
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a str, got {type(value).__name__}")
    return value


def _require_table(table: object) -> _symtable.SymbolTable:
    """Return *table* when it is a symbol table, otherwise raise ``TypeError``."""
    if not isinstance(table, _symtable.SymbolTable):
        raise TypeError(
            f"table must be a symtable.SymbolTable, got {type(table).__name__}"
        )
    return table


def _require_symbol(symbol: object) -> _symtable.Symbol:
    """Return *symbol* when it is a symbol, otherwise raise ``TypeError``."""
    if not isinstance(symbol, _symtable.Symbol):
        raise TypeError(
            f"symbol must be a symtable.Symbol, got {type(symbol).__name__}"
        )
    return symbol


def _collect(
    table: _symtable.SymbolTable, predicate: Callable[[_symtable.Symbol], bool]
) -> List[str]:
    """Return the names of the symbols in *table* matching *predicate*."""
    return [symbol.get_name() for symbol in table.get_symbols() if predicate(symbol)]


def build_symbol_table(
    code: str,
    filename: str = "<string>",
    compile_type: str = "exec",
) -> _symtable.SymbolTable:
    """Build the symbol table for a block of source code.

    Args:
        code: The Python source to analyse.
        filename: The name reported for the source in tracebacks and scopes.
        compile_type: One of ``"exec"``, ``"eval"``, or ``"single"``.

    Returns:
        The root :class:`symtable.SymbolTable` for the source.

    Raises:
        TypeError: If *code* or *filename* is not a string, or if
            *compile_type* is not a string.
        ValueError: If *compile_type* is not one of :data:`COMPILE_TYPES`.
        SyntaxError: If *code* cannot be parsed.

    Examples:
        >>> table = build_symbol_table("value = 1")
        >>> table.get_type()
        'module'
        >>> scope_identifiers(table)
        ['value']
    """
    source = _require_text(code, "code")
    source_name = _require_text(filename, "filename")
    mode = _require_text(compile_type, "compile_type")
    if mode not in COMPILE_TYPES:
        raise ValueError(
            f"compile_type must be one of {', '.join(COMPILE_TYPES)}, got {mode!r}"
        )
    return _symtable.symtable(source, source_name, mode)


def _module_source(name: str) -> str:
    """Return the path of the Python source file of the module *name*."""
    try:
        spec = importlib.util.find_spec(name)
    except (ImportError, ValueError) as exc:
        raise ImportError(f"cannot find the source of module {name!r}") from exc
    if spec is None or spec.origin is None:
        raise ImportError(f"cannot find the source of module {name!r}")
    origin = spec.origin
    if not origin.endswith(".py"):
        raise ImportError(f"module {name!r} has no Python source file")
    return origin


def lookup_symbol_table(
    name: str, filename: Optional[str] = None
) -> _symtable.SymbolTable:
    """Look up the symbol table of an importable module.

    The module is located with :func:`importlib.util.find_spec` and its
    source file is analysed without importing it.

    Args:
        name: The name of the module to inspect.
        filename: The path of the module source file, when it cannot be
            located automatically.

    Returns:
        The module's :class:`symtable.SymbolTable`.

    Raises:
        TypeError: If *name* or *filename* is not a string.
        ValueError: If *name* is empty.
        ImportError: If the module or its source file cannot be found.
        OSError: If the source file cannot be read.

    Examples:
        >>> table = lookup_symbol_table("json")
        >>> table.get_type()
        'module'
    """
    module_name = _require_text(name, "name")
    if not module_name:
        raise ValueError("name must not be empty")
    source_name = filename
    if source_name is None:
        source_name = _module_source(module_name)
    else:
        source_name = _require_text(filename, "filename")
    source = Path(source_name).read_text(encoding="utf-8")
    return build_symbol_table(source, source_name, "exec")


def scope_type(table: _symtable.SymbolTable) -> str:
    """Return the type of a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        One of ``"module"``, ``"function"``, ``"class"``, ``"annotation"``,
        or ``"comprehension"``.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return _require_table(table).get_type()


def scope_identifiers(table: _symtable.SymbolTable) -> List[str]:
    """Return the names bound in a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        The identifiers of the scope, in source order.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return list(_require_table(table).get_identifiers())


def child_scopes(table: _symtable.SymbolTable) -> List[_symtable.SymbolTable]:
    """Return the nested scopes of a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        The child symbol tables of *table*.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return list(_require_table(table).get_children())


def iter_scopes(
    table: _symtable.SymbolTable,
) -> Iterator[Tuple[Tuple[str, ...], _symtable.SymbolTable]]:
    """Walk a scope tree depth first.

    Args:
        table: The root symbol table to walk.

    Yields:
        Tuples of ``(path, table)`` where *path* is the tuple of scope names
        leading to the yielded table.

    Raises:
        TypeError: If *table* is not a symbol table.

    Examples:
        >>> table = build_symbol_table("def outer():\\n    pass")
        >>> [path for path, _ in iter_scopes(table)]
        [(), ('outer',)]
    """
    root = _require_table(table)
    stack: List[Tuple[Tuple[str, ...], _symtable.SymbolTable]] = [((), root)]
    while stack:
        path, current = stack.pop()
        yield path, current
        for child in reversed(child_scopes(current)):
            stack.append((path + (child.get_name(),), child))


def find_scope(
    table: _symtable.SymbolTable, name: str
) -> Optional[_symtable.SymbolTable]:
    """Find a nested scope by name.

    Args:
        table: The root symbol table to search.
        name: The name of the scope to find.

    Returns:
        The matching symbol table, or ``None`` when no scope matches.

    Raises:
        TypeError: If *table* is not a symbol table or *name* is not a string.
    """
    root = _require_table(table)
    scope_name = _require_text(name, "name")
    for _, current in iter_scopes(root):
        if current.get_name() == scope_name:
            return current
    return None


def describe_scope(table: _symtable.SymbolTable) -> Dict[str, Any]:
    """Summarize a scope.

    Args:
        table: The symbol table to describe.

    Returns:
        A dictionary with the ``name``, ``type``, ``lineno``, ``id``,
        ``identifiers``, and ``children`` of the scope.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    scope = _require_table(table)
    return {
        "name": scope.get_name(),
        "type": scope.get_type(),
        "lineno": scope.get_lineno(),
        "id": scope.get_id(),
        "identifiers": scope_identifiers(scope),
        "children": [child.get_name() for child in child_scopes(scope)],
    }


def symbol_flags(symbol: _symtable.Symbol) -> Dict[str, bool]:
    """Return the usage flags of a symbol.

    Args:
        symbol: The symbol to inspect.

    Returns:
        A dictionary mapping each ``is_*`` predicate of the symbol to a
        boolean. Predicates that the running interpreter does not provide
        (such as ``is_declared_nonlocal`` before Python 3.13) report
        ``False``.

    Raises:
        TypeError: If *symbol* is not a symbol.
    """
    entry = _require_symbol(symbol)
    flags: Dict[str, bool] = {}
    for name in _SYMBOL_FLAGS:
        predicate = getattr(entry, name, None)
        flags[name] = bool(predicate()) if callable(predicate) else False
    return flags


def symbol_info(table: _symtable.SymbolTable, name: str) -> Dict[str, Any]:
    """Describe a symbol bound in a scope.

    Args:
        table: The symbol table holding the symbol.
        name: The name of the symbol.

    Returns:
        A dictionary with the symbol ``name`` and its usage flags.

    Raises:
        TypeError: If *table* is not a symbol table or *name* is not a string.
        KeyError: If the scope does not bind *name*.
    """
    scope = _require_table(table)
    symbol_name = _require_text(name, "name")
    symbol = scope.lookup(symbol_name)
    if symbol is None:
        raise KeyError(f"{symbol_name!r} is not defined in scope {scope.get_name()!r}")
    info: Dict[str, Any] = {"name": symbol.get_name()}
    info.update(symbol_flags(symbol))
    return info


def free_variables(table: _symtable.SymbolTable) -> List[str]:
    """Return the free variables of a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        The names of the symbols bound in an enclosing scope.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return _collect(_require_table(table), lambda symbol: symbol.is_free())


def global_names(table: _symtable.SymbolTable) -> List[str]:
    """Return the global names of a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        The names of the symbols that are global in the scope.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return _collect(_require_table(table), lambda symbol: symbol.is_global())


def local_names(table: _symtable.SymbolTable) -> List[str]:
    """Return the local names of a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        The names of the symbols that are local to the scope.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return _collect(_require_table(table), lambda symbol: symbol.is_local())


def parameter_names(table: _symtable.SymbolTable) -> List[str]:
    """Return the parameter names of a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        The names of the symbols that are parameters of the scope.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return _collect(_require_table(table), lambda symbol: symbol.is_parameter())


def imported_names(table: _symtable.SymbolTable) -> List[str]:
    """Return the imported names of a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        The names of the symbols bound by an import statement.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return _collect(_require_table(table), lambda symbol: symbol.is_imported())


def assigned_names(table: _symtable.SymbolTable) -> List[str]:
    """Return the assigned names of a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        The names of the symbols that are assigned in the scope.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return _collect(_require_table(table), lambda symbol: symbol.is_assigned())


def referenced_names(table: _symtable.SymbolTable) -> List[str]:
    """Return the referenced names of a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        The names of the symbols that are referenced in the scope.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return _collect(_require_table(table), lambda symbol: symbol.is_referenced())


def nonlocal_names(table: _symtable.SymbolTable) -> List[str]:
    """Return the nonlocal names of a scope.

    Args:
        table: The symbol table to inspect.

    Returns:
        The names of the symbols declared ``nonlocal`` in the scope.

    Raises:
        TypeError: If *table* is not a symbol table.
    """
    return _collect(_require_table(table), lambda symbol: symbol.is_nonlocal())


def namespace_names(symbol: _symtable.Symbol) -> List[str]:
    """Return the names bound in the namespace a symbol introduces.

    A symbol that is the target of a class or function statement introduces
    a namespace; this function reports the identifiers bound inside that
    namespace.

    Args:
        symbol: The symbol to inspect.

    Returns:
        The identifiers of the namespace, or an empty list when the symbol
        is not bound to exactly one namespace.

    Raises:
        TypeError: If *symbol* is not a symbol.
    """
    entry = _require_symbol(symbol)
    try:
        namespace = entry.get_namespace()
    except ValueError:
        return []
    return list(namespace.get_identifiers())
SYMTABLE_UTILS

