#: The names of the control characters, in the order of their slots.
_CONTROL_CHARACTERS: tuple[tuple[str, int], ...] = (
    ("VINTR", VINTR),
    ("VQUIT", VQUIT),
    ("VERASE", VERASE),
    ("VKILL", VKILL),
    ("VEOF", VEOF),
    ("VTIME", VTIME),
    ("VMIN", VMIN),
    ("VSWTC", VSWTC),
    ("VSTART", VSTART),
    ("VSTOP", VSTOP),
    ("VSUSP", VSUSP),
    ("VEOL", VEOL),
    ("VREPRINT", VREPRINT),
    ("VDISCARD", VDISCARD),
