        with self.assertRaises(ValueError):
            open_url("http://x", new=5)
        with self.assertRaises(TypeError):
            open_url("http://x", new="1")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            open_url("http://x", autoraise="yes")  # type: ignore[arg-type]

