# --- xml_utils.py ---
cat > "$OUTPUT_DIR/xml_utils.py" <<'XML_UTILS'
"""XML parsing and generation utilities.

Provides helpers for parsing XML documents and strings, building XML elements,
converting between elements and dictionaries, querying with XPath, and
serializing elements back to strings using the standard library
``xml.etree.ElementTree`` module. All functions validate their inputs and raise
``TypeError`` or ``ValueError`` on invalid arguments.
"""

from __future__ import annotations

import os
import xml.etree.ElementTree as ET
from typing import Any, Optional, Union

__all__: list[str] = [
    "parse_xml",
    "parse_xml_string",
    "build_xml",
    "add_child",
    "set_attribute",
    "get_attribute",
    "element_to_dict",
    "dict_to_element",
    "find_elements",
    "find_element",
    "get_element_text",
    "set_element_text",
    "xml_to_string",
    "validate_well_formed",
]


def parse_xml(path: Union[str, os.PathLike[str]]) -> ET.ElementTree[ET.Element]:
    """Parse an XML file and return its :class:`~xml.etree.ElementTree.ElementTree`.

    Args:
        path: Path to the XML file.

    Returns:
        The parsed :class:`~xml.etree.ElementTree.ElementTree`.

    Raises:
        TypeError: If ``path`` is not a string or path-like object.
        FileNotFoundError: If the file does not exist.
        xml.etree.ElementTree.ParseError: If the file is not well-formed XML.

    Examples:
        >>> import tempfile, os
        >>> path = tempfile.mktemp(suffix=".xml")
        >>> with open(path, "w") as fh:
        ...     _ = fh.write("<root><child>text</child></root>")
        >>> tree = parse_xml(path)
        >>> tree.getroot().tag
        'root'
        >>> os.remove(path)
    """
    if not isinstance(path, (str, os.PathLike)):
        raise TypeError("path must be a string or path-like object")
    return ET.parse(os.fspath(path))


def parse_xml_string(text: str) -> ET.Element:
    """Parse an XML string and return its root :class:`~xml.etree.ElementTree.Element`.

    Args:
        text: The XML document as a string.

    Returns:
        The root :class:`~xml.etree.ElementTree.Element`.

    Raises:
        TypeError: If ``text`` is not a string.
        xml.etree.ElementTree.ParseError: If ``text`` is not well-formed XML.

    Examples:
        >>> parse_xml_string('<root><child a="1">text</child></root>').tag
        'root'
        >>> parse_xml_string('<root><child a="1">text</child></root>').find("child").text
        'text'
    """
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    return ET.fromstring(text)


def build_xml(tag: str, text: Optional[str] = None, **attributes: str) -> ET.Element:
    """Build an XML element with the given tag, optional text, and attributes.

    Args:
        tag: The element tag name.
        text: Optional text content of the element.
        attributes: Element attributes as keyword arguments.

    Returns:
        A new :class:`~xml.etree.ElementTree.Element`.

    Raises:
        TypeError: If ``tag`` or ``text`` is not a string, or if any attribute
            name or value is not a string.

    Examples:
        >>> root = build_xml("root", attr="value")
        >>> root.tag
        'root'
        >>> root.get("attr")
        'value'
    """
    if not isinstance(tag, str):
        raise TypeError("tag must be a string")
    if text is not None and not isinstance(text, str):
        raise TypeError("text must be a string or None")
    for key, value in attributes.items():
        if not isinstance(key, str) or not isinstance(value, str):
            raise TypeError("attribute names and values must be strings")
    element = ET.Element(tag)
    if text is not None:
        element.text = text
    for key, value in attributes.items():
        element.set(key, value)
    return element


def add_child(parent: ET.Element, child: ET.Element) -> None:
    """Append ``child`` as a sub-element of ``parent``.

    Args:
        parent: The parent element.
        child: The child element to append.

    Raises:
        TypeError: If either argument is not an :class:`~xml.etree.ElementTree.Element`.
    """
    if not isinstance(parent, ET.Element):
        raise TypeError("parent must be an Element")
    if not isinstance(child, ET.Element):
        raise TypeError("child must be an Element")
    parent.append(child)


def set_attribute(element: ET.Element, key: str, value: str) -> None:
    """Set the attribute ``key`` on ``element`` to ``value``.

    Args:
        element: The target element.
        key: The attribute name.
        value: The attribute value.

    Raises:
        TypeError: If ``element`` is not an Element, or ``key``/``value`` are
            not strings.
    """
    if not isinstance(element, ET.Element):
        raise TypeError("element must be an Element")
    if not isinstance(key, str) or not isinstance(value, str):
        raise TypeError("key and value must be strings")
    element.set(key, value)


def get_attribute(element: ET.Element, key: str, default: Optional[str] = None) -> Optional[str]:
    """Return the value of attribute ``key`` on ``element``, or ``default``.

    Args:
        element: The target element.
        key: The attribute name.
        default: Value returned when the attribute is absent.

    Returns:
        The attribute value, or ``default`` if the attribute is not present.

    Raises:
        TypeError: If ``element`` is not an Element, or ``key``/``default``
            have invalid types.
    """
    if not isinstance(element, ET.Element):
        raise TypeError("element must be an Element")
    if not isinstance(key, str):
        raise TypeError("key must be a string")
    if default is not None and not isinstance(default, str):
        raise TypeError("default must be a string or None")
    return element.get(key, default)


def element_to_dict(element: ET.Element) -> dict[str, Any]:
    """Convert ``element`` and its descendants into a nested dictionary.

    The dictionary has keys ``tag``, ``attributes``, ``text``, and ``children``,
    where ``children`` is a list of dictionaries produced recursively.

    Args:
        element: The element to convert.

    Returns:
        A nested dictionary representation of ``element``.

    Raises:
        TypeError: If ``element`` is not an :class:`~xml.etree.ElementTree.Element`.

    Examples:
        >>> tree = parse_xml_string('<root><child a="1">text</child></root>')
        >>> d = element_to_dict(tree)
        >>> d["tag"]
        'root'
        >>> d["children"][0]["tag"]
        'child'
        >>> d["children"][0]["attributes"]
        {'a': '1'}
    """
    if not isinstance(element, ET.Element):
        raise TypeError("element must be an Element")
    return {
        "tag": element.tag,
        "attributes": dict(element.attrib),
        "text": element.text,
        "children": [element_to_dict(child) for child in element],
    }


def dict_to_element(tag: str, data: dict[str, Any]) -> ET.Element:
    """Build an :class:`~xml.etree.ElementTree.Element` from a nested dictionary.

    The dictionary may contain ``attributes`` (dict), ``text`` (str), and
    ``children`` (list of dicts) keys, matching the output of
    :func:`element_to_dict`.

    Args:
        tag: The element tag name.
        data: A nested dictionary describing the element.

    Returns:
        A new :class:`~xml.etree.ElementTree.Element`.

    Raises:
        TypeError: If ``tag`` is not a string or ``data`` has an invalid shape.
    """
    if not isinstance(tag, str):
        raise TypeError("tag must be a string")
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")
    element = ET.Element(tag)
    attributes = data.get("attributes", {})
    if not isinstance(attributes, dict):
        raise TypeError("data['attributes'] must be a dictionary")
    for key, value in attributes.items():
        if not isinstance(key, str) or not isinstance(value, str):
            raise TypeError("attribute names and values must be strings")
        element.set(key, value)
    text = data.get("text")
    if text is not None:
        if not isinstance(text, str):
            raise TypeError("data['text'] must be a string or None")
        element.text = text
    children = data.get("children", [])
    if not isinstance(children, list):
        raise TypeError("data['children'] must be a list")
    for child in children:
        if not isinstance(child, dict):
            raise TypeError("each child must be a dictionary")
        child_tag = child.get("tag")
        if not isinstance(child_tag, str):
            raise TypeError("each child must have a string 'tag'")
        child_element = dict_to_element(child_tag, child)
        element.append(child_element)
    return element


def find_elements(element: ET.Element, xpath: str) -> list[ET.Element]:
    """Return all elements matching ``xpath`` relative to ``element``.

    Args:
        element: The element to search within.
        xpath: An XPath expression.

    Returns:
        A list of matching :class:`~xml.etree.ElementTree.Element` objects.

    Raises:
        TypeError: If ``element`` is not an Element or ``xpath`` is not a string.
    """
    if not isinstance(element, ET.Element):
        raise TypeError("element must be an Element")
    if not isinstance(xpath, str):
        raise TypeError("xpath must be a string")
    return element.findall(xpath)


def find_element(element: ET.Element, xpath: str) -> Optional[ET.Element]:
    """Return the first element matching ``xpath`` relative to ``element``.

    Args:
        element: The element to search within.
        xpath: An XPath expression.

    Returns:
        The first matching element, or ``None`` if no match is found.

    Raises:
        TypeError: If ``element`` is not an Element or ``xpath`` is not a string.
    """
    if not isinstance(element, ET.Element):
        raise TypeError("element must be an Element")
    if not isinstance(xpath, str):
        raise TypeError("xpath must be a string")
    return element.find(xpath)


def get_element_text(
    element: ET.Element, xpath: str, default: Optional[str] = None
) -> Optional[str]:
    """Return the text content of the first element matching ``xpath``.

    Args:
        element: The element to search within.
        xpath: An XPath expression locating the target element.
        default: Value returned when no matching element is found.

    Returns:
        The text content of the matched element, or ``default``.

    Raises:
        TypeError: If ``element`` is not an Element, ``xpath`` is not a string,
            or ``default`` is not a string or None.
    """
    if not isinstance(element, ET.Element):
        raise TypeError("element must be an Element")
    if not isinstance(xpath, str):
        raise TypeError("xpath must be a string")
    if default is not None and not isinstance(default, str):
        raise TypeError("default must be a string or None")
    found = element.find(xpath)
    if found is None:
        return default
    return found.text


def set_element_text(element: ET.Element, text: str) -> None:
    """Set the text content of ``element`` to ``text``.

    Args:
        element: The target element.
        text: The text content to set.

    Raises:
        TypeError: If ``element`` is not an Element or ``text`` is not a string.
    """
    if not isinstance(element, ET.Element):
        raise TypeError("element must be an Element")
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    element.text = text


def xml_to_string(element: ET.Element, xml_declaration: bool = True) -> str:
    """Serialize ``element`` and its descendants to an XML string.

    Args:
        element: The element to serialize.
        xml_declaration: Whether to include an XML declaration.

    Returns:
        The XML document as a string.

    Raises:
        TypeError: If ``element`` is not an Element or ``xml_declaration``
            is not a bool.
    """
    if not isinstance(element, ET.Element):
        raise TypeError("element must be an Element")
    if not isinstance(xml_declaration, bool):
        raise TypeError("xml_declaration must be a bool")
    return ET.tostring(element, encoding="unicode", xml_declaration=xml_declaration)


def validate_well_formed(text: str) -> bool:
    """Return ``True`` if ``text`` is well-formed XML, otherwise ``False``.

    Args:
        text: The candidate XML document as a string.

    Returns:
        ``True`` if ``text`` parses as well-formed XML, otherwise ``False``.

    Raises:
        TypeError: If ``text`` is not a string.

    Examples:
        >>> validate_well_formed("<root/>")
        True
        >>> validate_well_formed("<root>")
        False
    """
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    try:
        ET.fromstring(text)
    except ET.ParseError:
        return False
    return True


if __name__ == "__main__":
    import doctest

    doctest.testmod()
XML_UTILS

# --- tests/test_xml_utils.py ---
cat > "$OUTPUT_DIR/tests/test_xml_utils.py" <<'TEST_XML_UTILS'
"""Unit tests for xml_utils module."""

import tempfile
import unittest
import xml.etree.ElementTree as ET

from xml_utils import (
    add_child,
    build_xml,
    dict_to_element,
    element_to_dict,
    find_element,
    find_elements,
    get_attribute,
    get_element_text,
    parse_xml,
    parse_xml_string,
    set_attribute,
    set_element_text,
    validate_well_formed,
    xml_to_string,
)

SIMPLE_XML = '<root><child a="1">text</child><child a="2">more</child></root>'


class TestParseXmlString(unittest.TestCase):
    def test_parses_valid_xml(self):
        root = parse_xml_string(SIMPLE_XML)
        self.assertIsInstance(root, ET.Element)
        self.assertEqual(root.tag, "root")

    def test_child_attributes_and_text(self):
        root = parse_xml_string(SIMPLE_XML)
        first = root.find("child")
        self.assertIsNotNone(first)
        self.assertEqual(first.get("a"), "1")
        self.assertEqual(first.text, "text")

    def test_invalid_xml_raises(self):
        with self.assertRaises(ET.ParseError):
            parse_xml_string("<root>")

    def test_type_errors(self):
        with self.assertRaises(TypeError):
            parse_xml_string(123)  # type: ignore[arg-type]


class TestParseXml(unittest.TestCase):
    def test_parses_file(self):
        with tempfile.NamedTemporaryFile(mode="w", suffix=".xml", delete=False) as fh:
            fh.write(SIMPLE_XML)
            path = fh.name
        try:
            tree = parse_xml(path)
            self.assertIsInstance(tree, ET.ElementTree)
            self.assertEqual(tree.getroot().tag, "root")
        finally:
            import os

            os.remove(path)

    def test_type_errors(self):
        with self.assertRaises(TypeError):
            parse_xml(123)  # type: ignore[arg-type]


class TestBuildXml(unittest.TestCase):
    def test_builds_element_with_tag_and_text(self):
        element = build_xml("greeting", text="hello")
        self.assertEqual(element.tag, "greeting")
        self.assertEqual(element.text, "hello")

    def test_builds_element_with_attributes(self):
        element = build_xml("node", id="42", active="true")
        self.assertEqual(element.get("id"), "42")
        self.assertEqual(element.get("active"), "true")

    def test_type_errors(self):
        with self.assertRaises(TypeError):
            build_xml(123)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            build_xml("node", text=123)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            build_xml("node", id=123)  # type: ignore[arg-type]


class TestAddChild(unittest.TestCase):
    def test_appends_child(self):
        parent = build_xml("parent")
        child = build_xml("child")
        add_child(parent, child)
        self.assertEqual(len(parent), 1)
        self.assertEqual(parent[0].tag, "child")

    def test_type_errors(self):
        parent = build_xml("parent")
        with self.assertRaises(TypeError):
            add_child(parent, "not an element")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            add_child("not an element", build_xml("child"))  # type: ignore[arg-type]


class TestSetGetAttribute(unittest.TestCase):
    def test_set_and_get_attribute(self):
        element = build_xml("node")
        set_attribute(element, "key", "value")
        self.assertEqual(get_attribute(element, "key"), "value")

    def test_get_attribute_default(self):
        element = build_xml("node")
        self.assertIsNone(get_attribute(element, "missing"))
        self.assertEqual(get_attribute(element, "missing", default="n/a"), "n/a")

    def test_type_errors(self):
        element = build_xml("node")
        with self.assertRaises(TypeError):
            set_attribute(element, "k", 123)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            get_attribute(element, 123)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            get_attribute(element, "k", default=123)  # type: ignore[arg-type]


class TestElementToDict(unittest.TestCase):
    def test_converts_element_to_dict(self):
        root = parse_xml_string(SIMPLE_XML)
        d = element_to_dict(root)
        self.assertEqual(d["tag"], "root")
        self.assertEqual(d["attributes"], {})
        self.assertEqual(len(d["children"]), 2)
        self.assertEqual(d["children"][0]["tag"], "child")
        self.assertEqual(d["children"][0]["attributes"], {"a": "1"})
        self.assertEqual(d["children"][0]["text"], "text")

    def test_type_errors(self):
        with self.assertRaises(TypeError):
            element_to_dict("not an element")  # type: ignore[arg-type]


class TestDictToElement(unittest.TestCase):
    def test_rebuilds_element_from_dict(self):
        root = parse_xml_string(SIMPLE_XML)
        d = element_to_dict(root)
        rebuilt = dict_to_element("root", d)
        self.assertEqual(rebuilt.tag, "root")
        self.assertEqual(len(rebuilt), 2)
        self.assertEqual(rebuilt[0].get("a"), "1")
        self.assertEqual(rebuilt[0].text, "text")

    def test_roundtrip_preserves_structure(self):
        root = parse_xml_string("<outer><inner>value</inner></outer>")
        d = element_to_dict(root)
        rebuilt = dict_to_element(d["tag"], d)
        self.assertEqual(xml_to_string(rebuilt), xml_to_string(root))

    def test_type_errors(self):
        with self.assertRaises(TypeError):
            dict_to_element(123, {})  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            dict_to_element("tag", "not a dict")  # type: ignore[arg-type]


class TestFindElements(unittest.TestCase):
    def test_finds_matching_elements(self):
        root = parse_xml_string(SIMPLE_XML)
        children = find_elements(root, "child")
        self.assertEqual(len(children), 2)
        self.assertEqual([c.get("a") for c in children], ["1", "2"])

    def test_type_errors(self):
        root = build_xml("root")
        with self.assertRaises(TypeError):
            find_elements(root, 123)  # type: ignore[arg-type]


class TestFindElement(unittest.TestCase):
    def test_finds_first_matching_element(self):
        root = parse_xml_string(SIMPLE_XML)
        child = find_element(root, "child")
        self.assertIsNotNone(child)
        self.assertEqual(child.get("a"), "1")

    def test_returns_none_when_missing(self):
        root = build_xml("root")
        self.assertIsNone(find_element(root, "missing"))

    def test_type_errors(self):
        root = build_xml("root")
        with self.assertRaises(TypeError):
            find_element(root, 123)  # type: ignore[arg-type]


class TestGetSetElementText(unittest.TestCase):
    def test_get_element_text(self):
        root = parse_xml_string(SIMPLE_XML)
        self.assertEqual(get_element_text(root, "child"), "text")

    def test_get_element_text_default(self):
        root = build_xml("root")
        self.assertIsNone(get_element_text(root, "missing"))
        self.assertEqual(get_element_text(root, "missing", default="n/a"), "n/a")

    def test_set_element_text(self):
        element = build_xml("node")
        set_element_text(element, "new text")
        self.assertEqual(element.text, "new text")

    def test_type_errors(self):
        root = build_xml("root")
        with self.assertRaises(TypeError):
            get_element_text(root, 123)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            get_element_text(root, "child", default=123)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            set_element_text(root, 123)  # type: ignore[arg-type]


class TestXmlToString(unittest.TestCase):
    def test_serializes_element(self):
        element = build_xml("empty")
        self.assertEqual(xml_to_string(element, xml_declaration=False), "<empty />")

    def test_serializes_with_children(self):
        parent = build_xml("parent")
        add_child(parent, build_xml("child", text="hi"))
        result = xml_to_string(parent, xml_declaration=False)
        self.assertIn("<child>hi</child>", result)

    def test_type_errors(self):
        element = build_xml("node")
        with self.assertRaises(TypeError):
            xml_to_string(element, xml_declaration="yes")  # type: ignore[arg-type]


class TestValidateWellFormed(unittest.TestCase):
    def test_valid_xml_returns_true(self):
        self.assertTrue(validate_well_formed("<root/>"))
        self.assertTrue(validate_well_formed(SIMPLE_XML))

    def test_invalid_xml_returns_false(self):
        self.assertFalse(validate_well_formed("<root>"))
        self.assertFalse(validate_well_formed("not xml at all"))

    def test_type_errors(self):
        with self.assertRaises(TypeError):
            validate_well_formed(123)  # type: ignore[arg-type]


if __name__ == "__main__":
    unittest.main()
TEST_XML_UTILS

# --- xmlrpc_utils.py ---
cat > "$OUTPUT_DIR/xmlrpc_utils.py" <<'XMLRPC_UTILS'
"""XML-RPC utilities wrapping the standard library :mod:`xmlrpc` package.

The module covers both halves of the protocol: the client half
(:mod:`xmlrpc.client`) and the server half (:mod:`xmlrpc.server`).  Every
helper validates its arguments before the standard library is reached, so a
caller gets a clear ``TypeError`` or ``ValueError`` instead of a malformed
request.

The encoding helpers are pure computation and never touch the network.  The
helpers that would open a connection (``create_proxy``) or bind a socket
(``create_server``, ``create_multi_path_server``) only build the standard
library objects, so the caller stays in control of when a connection is
attempted.
"""

from __future__ import annotations

from typing import Any, Sequence
from xmlrpc import client as _client
from xmlrpc import server as _server

__all__: list[str] = [
    "Binary",
    "DateTime",
    "Error",
    "Fault",
    "Marshaller",
    "MultiCall",
    "MultiCallIterator",
    "ProtocolError",
    "ResponseError",
    "SafeTransport",
    "ServerProxy",
    "Transport",
    "Unmarshaller",
    "CGIXMLRPCRequestHandler",
    "MultiPathXMLRPCServer",
    "SimpleXMLRPCDispatcher",
    "SimpleXMLRPCRequestHandler",
    "SimpleXMLRPCServer",
    "build_request",
    "create_dispatcher",
    "create_marshaller",
    "create_multi_path_server",
    "create_proxy",
    "create_server",
    "create_transport",
    "dumps_value",
    "list_public_methods",
    "loads_value",
    "marshal_params",
    "parse_method_call",
    "parse_method_response",
    "register_function",
    "register_instance",
    "register_introspection_functions",
    "register_multicall_functions",
    "resolve_dotted_attribute",
    "unmarshal_params",
]

Error = _client.Error
Fault = _client.Fault
ProtocolError = _client.ProtocolError
ResponseError = _client.ResponseError
Binary = _client.Binary
DateTime = _client.DateTime
Marshaller = _client.Marshaller
Unmarshaller = _client.Unmarshaller
Transport = _client.Transport
SafeTransport = _client.SafeTransport
ServerProxy = _client.ServerProxy
MultiCall = _client.MultiCall
MultiCallIterator = _client.MultiCallIterator

SimpleXMLRPCServer = _server.SimpleXMLRPCServer
MultiPathXMLRPCServer = _server.MultiPathXMLRPCServer
SimpleXMLRPCRequestHandler = _server.SimpleXMLRPCRequestHandler
CGIXMLRPCRequestHandler = _server.CGIXMLRPCRequestHandler
SimpleXMLRPCDispatcher = _server.SimpleXMLRPCDispatcher


def _require_params(params: object) -> tuple[Any, ...]:
    """Return *params* as a tuple of XML-RPC arguments."""
    if isinstance(params, (str, bytes, bytearray)):
        raise TypeError("params must be a list or tuple, not a string")
    if not isinstance(params, (list, tuple)):
        raise TypeError(f"params must be a list or tuple, got {type(params).__name__}")
    return tuple(params)


def _require_document(document: object) -> str | bytes:
    """Return *document* as the text or bytes of an XML-RPC document."""
    if isinstance(document, (str, bytes, bytearray)):
        return bytes(document) if isinstance(document, bytearray) else document
    raise TypeError(f"document must be a str or bytes, got {type(document).__name__}")


def _require_name(name: object, label: str) -> str:
    """Return *name* when it is a usable, non-empty identifier."""
    if not isinstance(name, str):
        raise TypeError(f"{label} must be a str, got {type(name).__name__}")
    if not name:
        raise ValueError(f"{label} must not be empty")
    return name


def _require_bool(value: object, label: str) -> bool:
    """Return *value* when it is a boolean."""
    if not isinstance(value, bool):
        raise TypeError(f"{label} must be a bool, got {type(value).__name__}")
    return value


def dumps_value(
    params: Sequence[Any],
    methodname: str | None = None,
    methodresponse: bool | None = None,
    encoding: str | None = None,
    allow_none: bool = False,
) -> str:
    """Encode XML-RPC arguments into a request or response document.

    Args:
        params: The arguments of the call or the result of the response.
        methodname: The name of the method being called.
        methodresponse: Whether the document is a response.
        encoding: The text encoding of the document.
        allow_none: Whether ``None`` may be marshalled.

    Returns:
        The encoded document.
    """
    values = _require_params(params)
    if methodname is not None:
        _require_name(methodname, "methodname")
    if methodresponse is not None:
        _require_bool(methodresponse, "methodresponse")
    if encoding is not None and not isinstance(encoding, str):
        raise TypeError(f"encoding must be a str or None, got {type(encoding).__name__}")
    _require_bool(allow_none, "allow_none")
    if methodresponse and len(values) != 1:
        raise ValueError("a response document must carry exactly one value")
    return _client.dumps(
        values,
        methodname=methodname,
        methodresponse=methodresponse,
        encoding=encoding,
        allow_none=allow_none,
    )


def loads_value(
    document: str | bytes,
    use_datetime: bool = False,
    use_builtin_types: bool = False,
) -> tuple[tuple[Any, ...], str | None]:
    """Decode an XML-RPC document into its arguments and method name.

    Args:
        document: The document to decode.
        use_datetime: Whether dates are decoded as ``datetime`` objects.
        use_builtin_types: Whether binary and date values use builtin types.

    Returns:
        A tuple of the decoded arguments and the method name.  The method name
        is ``None`` for a response document.
    """
    payload = _require_document(document)
    _require_bool(use_datetime, "use_datetime")
    _require_bool(use_builtin_types, "use_builtin_types")
    params, methodname = _client.loads(
        payload,
        use_datetime=use_datetime,
        use_builtin_types=use_builtin_types,
    )
    return params, methodname


def build_request(methodname: str, params: Sequence[Any] = ()) -> str:
    """Build an XML-RPC method call document.

    Args:
        methodname: The name of the method to call.
        params: The arguments of the call.

    Returns:
        The encoded method call document.
    """
    name = _require_name(methodname, "methodname")
    values = _require_params(params)
    return _client.dumps(values, methodname=name)


def parse_method_call(document: str | bytes) -> tuple[str, tuple[Any, ...]]:
    """Parse an XML-RPC method call document.

    Args:
        document: The method call document.

    Returns:
        A tuple of the method name and the call arguments.
    """
    payload = _require_document(document)
    params, methodname = _client.loads(payload)
    if not methodname:
        raise ValueError("document does not contain a method call")
    return methodname, params


def parse_method_response(document: str | bytes) -> tuple[Any, ...]:
    """Parse an XML-RPC method response document.

    Args:
        document: The method response document.

    Returns:
        The result of the call.

    Raises:
        Fault: When the document carries a fault instead of a result.
    """
    payload = _require_document(document)
    params, methodname = _client.loads(payload)
    if methodname:
        raise ValueError("document contains a method call, not a method response")
    return params


def marshal_params(params: Sequence[Any]) -> str:
    """Encode XML-RPC arguments as a ``<params>`` document.

    Args:
        params: The arguments to encode.

    Returns:
        The encoded ``<params>`` document.
    """
    values = _require_params(params)
    marshaller = _client.Marshaller()
    return marshaller.dumps(values)


def unmarshal_params(document: str | bytes) -> tuple[Any, ...]:
    """Decode a ``<params>`` document into its arguments.

    Args:
        document: The document to decode.

    Returns:
        The decoded arguments.
    """
    payload = _require_document(document)
    params, _methodname = _client.loads(payload)
    return params


def create_marshaller(encoding: str | None = None, allow_none: bool = False) -> Marshaller:
    """Create a marshaller for XML-RPC values.

    Args:
        encoding: The text encoding of the produced documents.
        allow_none: Whether ``None`` may be marshalled.
    """
    if encoding is not None and not isinstance(encoding, str):
        raise TypeError(f"encoding must be a str or None, got {type(encoding).__name__}")
    _require_bool(allow_none, "allow_none")
    return _client.Marshaller(encoding=encoding, allow_none=allow_none)


def create_transport(
    use_datetime: bool = False,
    use_builtin_types: bool = False,
    *,
    headers: Sequence[tuple[str, str]] = (),
) -> Transport:
    """Create the transport used by a client proxy.

    Args:
        use_datetime: Whether dates are decoded as ``datetime`` objects.
        use_builtin_types: Whether binary and date values use builtin types.
        headers: Extra HTTP headers sent with every request.
    """
    _require_bool(use_datetime, "use_datetime")
    _require_bool(use_builtin_types, "use_builtin_types")
    if not isinstance(headers, (list, tuple)):
        raise TypeError(f"headers must be a list or tuple, got {type(headers).__name__}")
    return _client.Transport(
        use_datetime=use_datetime,
        use_builtin_types=use_builtin_types,
        headers=tuple(headers),
    )


def create_proxy(
    uri: str,
    transport: Transport | None = None,
    encoding: str | None = None,
    verbose: bool = False,
    allow_none: bool = False,
    use_datetime: bool = False,
    use_builtin_types: bool = False,
    *,
    headers: Sequence[tuple[str, str]] = (),
    context: Any = None,
) -> ServerProxy:
    """Create a client proxy for an XML-RPC server.

    The proxy is lazy: no connection is opened until a remote method is
    called.

    Args:
        uri: The URI of the server.
        transport: The transport used for the requests.
        encoding: The text encoding of the requests.
        verbose: Whether the requests are logged.
        allow_none: Whether ``None`` may be sent.
        use_datetime: Whether dates are decoded as ``datetime`` objects.
        use_builtin_types: Whether binary and date values use builtin types.
        headers: Extra HTTP headers sent with every request.
        context: The SSL context used for an ``https`` URI.
    """
    _require_name(uri, "uri")
    if transport is not None and not isinstance(transport, Transport):
        raise TypeError(f"transport must be a Transport or None, got {type(transport).__name__}")
    if encoding is not None and not isinstance(encoding, str):
        raise TypeError(f"encoding must be a str or None, got {type(encoding).__name__}")
    _require_bool(verbose, "verbose")
    _require_bool(allow_none, "allow_none")
    _require_bool(use_datetime, "use_datetime")
    _require_bool(use_builtin_types, "use_builtin_types")
    if not isinstance(headers, (list, tuple)):
        raise TypeError(f"headers must be a list or tuple, got {type(headers).__name__}")
    return _client.ServerProxy(
        uri,
        transport=transport,
        encoding=encoding,
        verbose=verbose,
        allow_none=allow_none,
        use_datetime=use_datetime,
        use_builtin_types=use_builtin_types,
        headers=tuple(headers),
        context=context,
    )


def create_dispatcher(
    allow_none: bool = False,
    encoding: str | None = None,
    use_builtin_types: bool = False,
) -> SimpleXMLRPCDispatcher:
    """Create a dispatcher that maps remote calls onto local callables.

    The dispatcher is a plain mixin and does not open a socket, so it can be
    exercised without a server.

    Args:
        allow_none: Whether ``None`` may be sent.
        encoding: The text encoding of the responses.
        use_builtin_types: Whether binary and date values use builtin types.
    """
    _require_bool(allow_none, "allow_none")
    if encoding is not None and not isinstance(encoding, str):
        raise TypeError(f"encoding must be a str or None, got {type(encoding).__name__}")
    _require_bool(use_builtin_types, "use_builtin_types")
    return _server.SimpleXMLRPCDispatcher(
        allow_none=allow_none,
        encoding=encoding,
        use_builtin_types=use_builtin_types,
    )


def _require_dispatcher(dispatcher: object) -> SimpleXMLRPCDispatcher:
    """Return *dispatcher* when it is a dispatcher of the standard library."""
    if not isinstance(dispatcher, SimpleXMLRPCDispatcher):
        raise TypeError(
            f"dispatcher must be a SimpleXMLRPCDispatcher, got {type(dispatcher).__name__}"
        )
    return dispatcher


def register_function(
    dispatcher: SimpleXMLRPCDispatcher,
    function: Any = None,
    name: str | None = None,
) -> None:
    """Register a callable so that it can be called remotely.

    Args:
        dispatcher: The dispatcher the function is registered with.
        function: The callable to register.
        name: The name the function is registered under.
    """
    _require_dispatcher(dispatcher)
    if function is not None and not callable(function):
        raise TypeError(f"function must be callable or None, got {type(function).__name__}")
    if name is not None:
        _require_name(name, "name")
    dispatcher.register_function(function, name)


def register_instance(
    dispatcher: SimpleXMLRPCDispatcher,
    instance: Any,
    allow_dotted_names: bool = False,
) -> None:
    """Register an object so that its methods can be called remotely.

    Args:
        dispatcher: The dispatcher the instance is registered with.
        instance: The object to register.
        allow_dotted_names: Whether dotted method names are allowed.
    """
    _require_dispatcher(dispatcher)
    if instance is None:
        raise ValueError("instance must not be None")
    _require_bool(allow_dotted_names, "allow_dotted_names")
    dispatcher.register_instance(instance, allow_dotted_names)


def register_introspection_functions(dispatcher: SimpleXMLRPCDispatcher) -> None:
    """Register the ``system.*`` introspection methods with a dispatcher."""
    _require_dispatcher(dispatcher)
    dispatcher.register_introspection_functions()


def register_multicall_functions(dispatcher: SimpleXMLRPCDispatcher) -> None:
    """Register the ``system.multicall`` method with a dispatcher."""
    _require_dispatcher(dispatcher)
    dispatcher.register_multicall_functions()


def resolve_dotted_attribute(obj: Any, attr: str, allow_dotted_names: bool = True) -> Any:
    """Resolve a possibly dotted attribute path on *obj*.

    Args:
        obj: The object the attribute is resolved on.
        attr: The attribute path.
        allow_dotted_names: Whether dotted names are resolved step by step.

    Returns:
        The resolved attribute.
    """
    if obj is None:
        raise ValueError("obj must not be None")
    _require_name(attr, "attr")
    _require_bool(allow_dotted_names, "allow_dotted_names")
    return _server.resolve_dotted_attribute(obj, attr, allow_dotted_names)


def list_public_methods(obj: Any) -> list[str]:
    """Return the public methods of *obj*.

    Args:
        obj: The object to inspect.
    """
    if obj is None:
        raise ValueError("obj must not be None")
    return _server.list_public_methods(obj)


def create_server(
    addr: tuple[str, int],
    request_handler: type[SimpleXMLRPCRequestHandler] = SimpleXMLRPCRequestHandler,
    log_requests: bool = True,
    allow_none: bool = False,
    encoding: str | None = None,
    bind_and_activate: bool = True,
    use_builtin_types: bool = False,
) -> SimpleXMLRPCServer:
    """Create an XML-RPC server bound to *addr*.

    The server binds its socket unless ``bind_and_activate`` is false, so the
    caller stays in control of when the port is opened.

    Args:
        addr: The ``(host, port)`` address the server listens on.
        request_handler: The request handler class.
        log_requests: Whether requests are logged.
        allow_none: Whether ``None`` may be sent.
        encoding: The text encoding of the responses.
        bind_and_activate: Whether the socket is bound immediately.
        use_builtin_types: Whether binary and date values use builtin types.
    """
    if not isinstance(addr, tuple) or len(addr) != 2:
        raise TypeError("addr must be a (host, port) tuple")
    if not isinstance(addr[0], str):
        raise TypeError(f"addr host must be a str, got {type(addr[0]).__name__}")
    if not isinstance(addr[1], int) or isinstance(addr[1], bool):
        raise TypeError(f"addr port must be an int, got {type(addr[1]).__name__}")
    if not 0 <= addr[1] <= 65535:
        raise ValueError(f"addr port must be between 0 and 65535, got {addr[1]}")
    if not isinstance(request_handler, type) or not issubclass(
        request_handler, SimpleXMLRPCRequestHandler
    ):
        raise TypeError("request_handler must be a SimpleXMLRPCRequestHandler subclass")
    _require_bool(log_requests, "log_requests")
    _require_bool(allow_none, "allow_none")
    if encoding is not None and not isinstance(encoding, str):
        raise TypeError(f"encoding must be a str or None, got {type(encoding).__name__}")
    _require_bool(bind_and_activate, "bind_and_activate")
    _require_bool(use_builtin_types, "use_builtin_types")
    return _server.SimpleXMLRPCServer(
        addr,
        requestHandler=request_handler,
        logRequests=log_requests,
        allow_none=allow_none,
        encoding=encoding,
        bind_and_activate=bind_and_activate,
        use_builtin_types=use_builtin_types,
    )


def create_multi_path_server(
    addr: tuple[str, int],
    paths: Any,
    request_handler: type[SimpleXMLRPCRequestHandler] = SimpleXMLRPCRequestHandler,
    log_requests: bool = True,
    allow_none: bool = False,
    encoding: str | None = None,
    bind_and_activate: bool = True,
    use_builtin_types: bool = False,
) -> MultiPathXMLRPCServer:
    """Create an XML-RPC server that dispatches on the request path.

    Args:
        addr: The ``(host, port)`` address the server listens on.
        paths: A mapping of request paths onto dispatchers.
        request_handler: The request handler class.
        log_requests: Whether requests are logged.
        allow_none: Whether ``None`` may be sent.
        encoding: The text encoding of the responses.
        bind_and_activate: Whether the socket is bound immediately.
        use_builtin_types: Whether binary and date values use builtin types.
    """
    if not isinstance(addr, tuple) or len(addr) != 2:
        raise TypeError("addr must be a (host, port) tuple")
    if not isinstance(addr[0], str):
        raise TypeError(f"addr host must be a str, got {type(addr[0]).__name__}")
    if not isinstance(addr[1], int) or isinstance(addr[1], bool):
        raise TypeError(f"addr port must be an int, got {type(addr[1]).__name__}")
    if not 0 <= addr[1] <= 65535:
        raise ValueError(f"addr port must be between 0 and 65535, got {addr[1]}")
    if paths is None:
        raise ValueError("paths must not be None")
    if not isinstance(request_handler, type) or not issubclass(
        request_handler, SimpleXMLRPCRequestHandler
    ):
        raise TypeError("request_handler must be a SimpleXMLRPCRequestHandler subclass")
    _require_bool(log_requests, "log_requests")
    _require_bool(allow_none, "allow_none")
    if encoding is not None and not isinstance(encoding, str):
        raise TypeError(f"encoding must be a str or None, got {type(encoding).__name__}")
    _require_bool(bind_and_activate, "bind_and_activate")
    _require_bool(use_builtin_types, "use_builtin_types")
    return _server.MultiPathXMLRPCServer(
        addr,
        requestHandler=request_handler,
        logRequests=log_requests,
        allow_none=allow_none,
        encoding=encoding,
        bind_and_activate=bind_and_activate,
        use_builtin_types=use_builtin_types,
    )
XMLRPC_UTILS

