class TestQuote(unittest.TestCase):
    """Verify percent-encoding a string."""

    def test_quote_matches_the_standard_library(self):
        self.assertEqual(quote("/a b/c"), _urllib_parse.quote("/a b/c"))
        self.assertEqual(quote("a&b=c"), _urllib_parse.quote("a&b=c"))

