class TestUrlencode(unittest.TestCase):
    """Verify encoding a query into a string."""

    def test_urlencode_matches_the_standard_library(self):
        self.assertEqual(
            urlencode({"q": "a b", "n": 1}), _urllib_parse.urlencode({"q": "a b", "n": 1})
        )
        self.assertEqual(
            urlencode([("q", "a b"), ("n", "1")]),
