        with mock.patch("smtpd_utils.SMTPServer") as m:
            m.return_value = mock.sentinel.server
            result = smtpd_utils.create_smtp_server(("localhost", 1025))
            self.assertIs(result, mock.sentinel.server)
            m.assert_called_once()

